          if (hp.length) push('trainer|goals-held|' + cu.id, 'students', t('pend.trainerHeldTitle'), t('pend.trainerHeldDetail', { name: cu.name || cu.email || '—', params: hp.map(p2 => t('gm.param.' + p2)).join(', ') }), t('pend.trainerHeldGo'));
