/* ---------- Sección «Consumo y cuotas» (SISTEMA) ----------
   AUTH-2026-11-05-252 (punto 164 de la cola; diseño
   DISENO-CONSUMO-CUOTAS-2026-11-05.md, aprobado por Ronald el
   2026-11-05 con su «2 si»): el panel de los TRES PISOS honestos,
   que NUNCA se suman entre sí (la banda A ya incluye a las demás;
   B y C la explican):
   · BANDA A — el total oficial del proyecto según Google (Cloud
     Monitoring) contra el cupo gratuito; el % es DERIVADO y va
     marcado «≈ del cupo», porque Google no publica ningún contador
     de cupo restante en el nivel gratuito, y Google NO desglosa el
     total por sección ni por usuario en ninguna superficie.
   · BANDA B — lo nuestro medido exacto: IA por alumno (los mismos
     contadores de los límites), el servidor por fuente, y los
     sellos del respaldo y de las herramientas.
   · BANDA C — la estimación de la app por sección (la cuentan los
     propios cargadores; su nota de estimación va SIEMPRE visible).
   Solo administrador: la sección vive en el registro ADMIN_SECTIONS
   (que solo pinta renderAdminZone con ROLE administrador) y la ruta
   del Worker exige el token del propietario. Abrir el panel cuesta
   CERO lecturas de Firestore: una llamada a la ruta (Google se
   cachea 5 minutos en el Worker) y lecturas KV. */
let ADM_QUOTA = null; /* última respuesta buena + su hora local */
async function quotaCall() {
  const ep = aiEndpoint();
  if (!ep) throw new Error('ai-off');
  const idToken = await auth.currentUser.getIdToken();
  const r = await fetch(ep + '/admin/quota', { headers: { Authorization: 'Bearer ' + idToken } });
  if (!r.ok) throw new Error('quota-' + r.status);
  return r.json();
}
function admSecMountQuotas(body) {
  body.innerHTML = `<p class="progress-hint">${esc(t('admq.hint'))}</p><div id="adm-quota-body"><p class="admuse-loading">${esc(t('admq.loading'))}</p></div>`;
  admQuotaRefresh();
}
function admQuotaRefresh() {
  const b = document.getElementById('adm-quota-body');
  if (!b) return;
  quotaCall().then(d => { ADM_QUOTA = { d, at: Date.now() }; admPaintQuota(false); })
    .catch(() => {
      if (ADM_QUOTA) admPaintQuota(true);
      else { const bb = document.getElementById('adm-quota-body'); if (bb) bb.innerHTML = `<p class="admuse-unavailable">${esc(t('admq.unavailable'))}</p>`; }
    });
}
function admqWhen() {
  return ADM_QUOTA ? new Date(ADM_QUOTA.at).toLocaleTimeString(LANG === 'es' ? 'es' : 'en', { hour: '2-digit', minute: '2-digit' }) : '';
}
function admqNum(n) {
  return (n == null || isNaN(n)) ? '—' : Number(n).toLocaleString(LANG === 'es' ? 'es' : 'en-US');
}
function admqBar(label, n, quota) {
  const has = n != null && !isNaN(n);
  const rawPct = has ? (Number(n) / quota) * 100 : null;
  const cls = rawPct == null ? '' : (rawPct >= 90 ? 'crit' : (rawPct >= 70 ? 'warn' : 'ok'));
  const wdt = rawPct == null ? 0 : Math.max(2, Math.min(100, rawPct));
  const pctTxt = rawPct == null ? '' : (rawPct >= 10 ? String(Math.round(rawPct)) : rawPct.toFixed(1));
  return `<div class="admq-bar"><div class="admq-barhead"><span>${esc(label)}</span><b>${admqNum(n)}</b></div>`
    + `<div class="admq-track"><div class="admq-fill ${cls}" style="width:${wdt}%"></div></div>`
    + `<div class="admq-barfoot">${rawPct == null ? esc(t('admq.noData')) : esc(t('admq.ofQuota', { pct: pctTxt, quota: admqNum(quota) }))}</div></div>`;
}
function admPaintQuota(stale) {
  const b = document.getElementById('adm-quota-body');
  if (!b || !ADM_QUOTA) return;
  const d = ADM_QUOTA.d;
  const A = d.bandA || {};
  let h = stale
    ? `<p class="admuse-stale">${esc(t('admq.stale', { when: admqWhen() }))}</p>`
    : `<p class="admuse-fetched">${esc(t('admq.fetchedAt', { when: admqWhen() }))}${A.fromCache ? ' · ' + esc(t('admq.fromCache')) : ''}</p>`;
  /* ── BANDA A: el total oficial de Google ── */
  h += `<div class="admq-band"><h4 class="admuse-aititle">${esc(t('admq.bandA'))}</h4><p class="progress-hint">${esc(t('admq.bandASub'))}</p>`;
  if (A.status === 'ok') {
    h += admqBar(t('admq.reads'), A.reads, 50000) + admqBar(t('admq.writes'), A.writes, 20000) + admqBar(t('admq.deletes'), A.deletes, 20000);
    if (A.quotaSeries && A.quotaSeries.found && A.quotaSeries.reads != null)
      h += `<p class="admq-line">✓ ${esc(t('admq.quotaDirect', { n: admqNum(A.quotaSeries.reads) }))}</p>`;
    if (A.rejects429 != null)
      h += `<p class="admq-line">⚠️ ${esc(t('admq.rejects', { n: admqNum(A.rejects429) }))}</p>`;
    const ageMin = A.fetchedAt ? Math.max(0, Math.round((Date.now() - Date.parse(A.fetchedAt)) / 60000)) : 0;
    h += `<p class="admq-note">${esc(t('admq.bandAFoot', { min: ageMin }))}</p>`;
  } else if (A.status === 'permission') {
    h += `<p class="admq-alert">${esc(t('admq.bandAPermission'))}</p>`;
  } else if (A.status === 'disabled') {
    h += `<p class="admq-alert">${esc(t('admq.bandADisabled'))}</p>`;
  } else {
    h += `<p class="admq-alert">${esc(t('admq.bandAError', { detail: String(A.detail || '') }))}</p>`;
  }
  h += `<p class="admq-note">${esc(t('admq.cacheNote'))}</p>`;
  h += `</div>`;
  /* ── BANDA B: lo nuestro, exacto ── */
  const B = d.bandB || {};
  const ia = B.ia || { users: [], total: 0 };
  h += `<div class="admq-band"><h4 class="admuse-aititle">${esc(t('admq.bandB'))}</h4><p class="progress-hint">${esc(t('admq.bandBSub'))}</p>`;
  h += `<div class="admq-card"><div class="admq-cardtitle">${esc(t('admq.iaTitle'))} · ${esc(t('admq.iaTotal', { n: admqNum(ia.total) }))}</div>`
    + `<p class="admq-small">${esc(t('admq.iaDay', { day: String(ia.day || '') }))}</p>`;
  if (Array.isArray(ia.users) && ia.users.length) {
    h += ia.users.map(u => `<div class="admq-srcrow"><span>${esc(admuseNameOf(u.uid).name)}</span><b>${admqNum(u.n)}</b></div>`).join('');
  } else {
    h += `<p class="admq-small">${esc(t('admq.iaNone'))}</p>`;
  }
  h += `</div>`;
  const SRC_LABEL = {
    'puerta-ia': 'admq.srcPuerta', 'despertador-resumen': 'admq.srcDespertadorResumen',
    'despertador-atencion': 'admq.srcDespertadorAtencion', 'despertador-semanal': 'admq.srcDespertadorSemanal',
    'rutas-admin': 'admq.srcRutas', 'correo-y-registro': 'admq.srcCorreo', 'otros': 'admq.srcOtros'
  };
  const wk = B.worker || {};
  const srcKeys = Object.keys(SRC_LABEL).filter(k => wk[k] && (wk[k].docs > 0 || wk[k].reqs > 0));
  h += `<div class="admq-card"><div class="admq-cardtitle">${esc(t('admq.serverTitle'))}</div><p class="admq-small">${esc(t('admq.dayChicago'))}</p>`;
  if (srcKeys.length) {
    h += srcKeys.map(k => `<div class="admq-srcrow"><span>${esc(t(SRC_LABEL[k]))}</span><b>${esc(t('admq.docsReqs', { docs: admqNum(wk[k].docs), reqs: admqNum(wk[k].reqs) }))}</b></div>`).join('');
  } else {
    h += `<p class="admq-small">${esc(t('admq.serverNone'))}</p>`;
  }
  if (wk.cuota429 && wk.cuota429.total > 0)
    h += `<p class="admq-line">⚠️ ${esc(t('admq.quota429', { first: String(wk.cuota429.first || ''), n: admqNum(wk.cuota429.total) }))}</p>`;
  else
    h += `<p class="admq-line">✓ ${esc(t('admq.quota429None'))}</p>`;
  h += `</div>`;
  const stamps = B.stamps || {};
  const stampCard = (titleKey, lineKey, s) => `<div class="admq-card"><div class="admq-cardtitle">${esc(t(titleKey))}</div>`
    + (s ? `<p class="admq-small">${esc(t(lineKey, { docs: admqNum(s.documentos), calls: admqNum(s.llamadas), when: admuseShortDate(String(s.at || '').slice(0, 10)) }))}</p>`
         : `<p class="admq-small">${esc(t('admq.noStamp'))}</p>`) + `</div>`;
  h += stampCard('admq.backupTitle', 'admq.backupLine', stamps.respaldo);
  h += stampCard('admq.toolsTitle', 'admq.toolsLine', stamps.herramientas);
  h += `</div>`;
  /* ── BANDA C: la app, estimación por sección ── */
  const C = d.bandC || { porSeccion: {}, sesiones: 0, usuarios: 0 };
  const SEC_LABEL = { arranque: 'admq.secArranque', inicio: 'admq.secInicio', comida: 'admq.secComida', entrenamiento: 'admq.secEntrenamiento', progreso: 'admq.secProgreso', otros: 'admq.secOtros' };
  h += `<div class="admq-band"><h4 class="admuse-aititle">${esc(t('admq.bandC'))}</h4><p class="admq-note">${esc(t('admq.bandCSub'))}</p><p class="admq-small">${esc(t('admq.dayChicago'))}</p>`;
  if (C.usuarios > 0) {
    h += `<p class="admq-small">${esc(t('admq.bandCSessions', { users: admqNum(C.usuarios), sessions: admqNum(C.sesiones) }))}</p>`;
    h += Object.keys(SEC_LABEL).map(k => {
      const v = (C.porSeccion && C.porSeccion[k]) || { server: 0, cache: 0 };
      return `<div class="admq-srcrow"><span>${esc(t(SEC_LABEL[k]))}</span><b>${esc(t('admq.serverDocs', { n: admqNum(v.server) }))} · ${esc(t('admq.cacheDocs', { n: admqNum(v.cache) }))}</b></div>`;
    }).join('');
  } else {
    h += `<p class="admq-small">${esc(t('admq.bandCNone'))}</p>`;
  }
  h += `</div>`;
  /* ── Últimos 7 días ── */
  const hist = Array.isArray(d.history) ? d.history : [];
  if (hist.length) {
    h += `<div class="admq-band"><h4 class="admuse-aititle">${esc(t('admq.histTitle'))}</h4>`;
    h += hist.map(r => `<div class="admq-hrow"><b>${esc(admuseShortDate(r.fecha))}</b>`
      + `<span>${esc(t('admq.hGoogle'))}: ${r.bandaA ? admqNum(r.bandaA.reads) : esc(t('admq.noData'))}</span>`
      + `<span>${esc(t('admq.hIa'))}: ${r.iaTotal == null ? esc(t('admq.noData')) : admqNum(r.iaTotal)}</span>`
      + `<span>${esc(t('admq.hServer'))}: ${r.workerDocs == null ? esc(t('admq.noData')) : admqNum(r.workerDocs)}</span>`
      + `<span>${esc(t('admq.hBackup'))}: ${r.respaldoDocs == null ? esc(t('admq.noData')) : admqNum(r.respaldoDocs)}</span>`
      + `<span>${esc(t('admq.hTools'))}: ${r.herramientasDocs == null ? esc(t('admq.noData')) : admqNum(r.herramientasDocs)}</span></div>`).join('');
    h += `</div>`;
  }
  h += `<div class="eval-actions"><button type="button" class="btn-primary" id="adm-quota-refresh">${esc(t('admq.refresh'))}</button></div>`;
  b.innerHTML = h;
  const rb = document.getElementById('adm-quota-refresh');
  if (rb) rb.addEventListener('click', () => admQuotaRefresh());
}
/* ---------- Sección «Límites y cuotas» (SISTEMA) ----------
   Punto 12 de la cola (pedido de Ronald 2026-11-01 18:42 CST):
   el registro EDITABLE del administrador con los topes de cada
   servicio (servicio · qué se mide · tope · periodo · notas).
   Es SOLO un registro de consulta y gobierno: editarlo NO cambia
   ningún límite real de ningún servicio — el aviso va visible en
   la cabecera de la sección (limreg.hint). Vive en
   app_settings/limits, documento SOLO del propietario por su
   propio bloque de reglas (delta aprobado por Ronald 2026-11-02,
   réplica del precedente mail_templates de AUTH-146); el
   documento no se borra jamás: las filas se editan o se retiran
   de la lista. Sin documento, la primera apertura del
   administrador lo SIEMBRA desde la app con las filas verificadas
   cifra a cifra el 2026-11-02 (una escritura del propietario,
   declarada). Guardar confirma SOLO tras el await (la disciplina
   de renderAiControlBox): en error, aviso de error y la vista
   vuelve a los valores guardados. */
const LIMREG_SEED_ROWS = [
  { service: 'Firestore (plan Spark)', measure: 'Lecturas de documentos', cap: '50.000', period: 'día', notes: 'Cuota publicada del plan Spark; el proyecto está en Spark $0.' },
  { service: 'Firestore (plan Spark)', measure: 'Escrituras de documentos', cap: '20.000', period: 'día', notes: 'Cuota publicada del plan Spark.' },
  { service: 'Firestore (plan Spark)', measure: 'Borrados de documentos', cap: '20.000', period: 'día', notes: 'Cuota publicada del plan Spark.' },
  { service: 'Firestore (plan Spark)', measure: 'Almacenamiento', cap: '1 GiB', period: 'total', notes: 'Cuota publicada del plan Spark.' },
  { service: 'Gemini (vía Worker)', measure: 'Gasto en IA de comidas y análisis', cap: '$250', period: 'mes', notes: 'Prepago, Nivel 1; recarga automática APAGADA. El saldo vive en Google AI Studio.' },
  { service: 'Umami (plan Hobby)', measure: 'Eventos de analítica', cap: '100.000', period: 'mes', notes: 'Eventos incluidos en el plan Umami Cloud Hobby.' },
  { service: 'IA por usuario', measure: 'Análisis por usuario', cap: '10 por defecto · Ronald 30 · piloto y David: sin límite', period: 'día', notes: 'Del KV M8_TOPES del Worker, verificado en vivo el 2026-11-02.' },
  { service: 'Aprobaciones por entrenador', measure: 'Cuentas nuevas que un entrenador puede aprobar', cap: '1', period: 'por entrenador', notes: 'Valor VIVO en app_settings/approvals (2026-11-02). El valor de diseño registrado era 5: su decisión sigue pendiente.' },
  { service: 'Membresías (cupo de alumnos)', measure: 'Alumnos por entrenador según nivel', cap: 'Básico 5 · Premium 10 · Élite 30', period: 'por entrenador', notes: 'Cifra de diseño: el catálogo no existe en producción y la facturación sigue apagada.' },
  { service: 'Correo automático (Comunicaciones)', measure: 'Correos enviados por la app', cap: '450', period: 'día', notes: 'Tope en la propia app (COMMS_CAP), por debajo del límite del buzón.' },
];
let LIMREG_ROWS = null;   // null = aún no leído en esta sesión
function admSecMountLimits(body) {
  body.innerHTML = `<p class="progress-hint">${esc(t('limreg.hint'))}</p><div id="limreg-box"><div class="wempty">${esc(t('limreg.loading'))}</div></div>`;
  limregLoad();
}
function admSecRefreshLimits() { if (document.getElementById('limreg-box')) limregLoad(); }
async function limregLoad() {
  const box = document.getElementById('limreg-box');
  if (!box) return;
  if (!(IS_OWNER && ROLE === 'administrador')) { box.innerHTML = ''; return; }
  try {
    const s = await getDoc(doc(db, 'app_settings', 'limits'));
    if (s.exists() && Array.isArray(s.data().rows)) {
      LIMREG_ROWS = s.data().rows;
    } else {
      LIMREG_ROWS = LIMREG_SEED_ROWS.map(r => ({ ...r }));
      await setDoc(doc(db, 'app_settings', 'limits'), { rows: LIMREG_ROWS, updatedAt: serverTimestamp(), updatedBy: auth.currentUser.uid });
    }
  } catch {
    toast(t('limreg.error'), true);
    if (!LIMREG_ROWS) { box.innerHTML = `<div class="wempty">${esc(t('limreg.error'))}</div>`; return; }
  }
  limregPaint();
}
function limregRowHTML(r) {
  const f = (k, ph) => `<label class="limreg-field"><span class="muted">${esc(t('limreg.' + k))}</span><input type="text" data-limreg="${k}" value="${esc(r[k.replace('col', '').toLowerCase()] || '')}" placeholder="${esc(ph || '')}"></label>`;
  return `<div class="limreg-row">`
    + f('colService') + f('colMeasure') + f('colCap') + f('colPeriod') + f('colNotes')
    + `<div class="limreg-actions"><button type="button" class="btn-primary btn-sm" data-limreg-save>${esc(t('limreg.save'))}</button><button type="button" class="btn-ghost btn-sm" data-limreg-del>${esc(t('limreg.removeRow'))}</button></div></div>`;
}
function limregPaint() {
  const box = document.getElementById('limreg-box');
  if (!box || !LIMREG_ROWS) return;
  box.innerHTML = LIMREG_ROWS.map(limregRowHTML).join('')
    + `<div class="eval-actions"><button type="button" class="btn-ghost btn-sm" id="limreg-add">${esc(t('limreg.addRow'))}</button></div>`;
  box.querySelectorAll('[data-limreg-save]').forEach(b => b.addEventListener('click', () => limregSaveAll()));
  box.querySelectorAll('[data-limreg-del]').forEach(b => b.addEventListener('click', () => { const row = b.closest('.limreg-row'); if (row) row.remove(); limregSaveAll(); }));
  const add = document.getElementById('limreg-add');
  if (add) add.addEventListener('click', () => {
    add.closest('.eval-actions').insertAdjacentHTML('beforebegin', limregRowHTML({}));
    const rows = box.querySelectorAll('.limreg-row');
    const last = rows[rows.length - 1];
    if (last) {
      last.querySelector('[data-limreg-save]').addEventListener('click', () => limregSaveAll());
      last.querySelector('[data-limreg-del]').addEventListener('click', () => { last.remove(); limregSaveAll(); });
      const inp = last.querySelector('input'); if (inp) inp.focus();
    }
  });
}
function limregCollect() {
  const box = document.getElementById('limreg-box');
  if (!box) return [];
  const keys = ['service', 'measure', 'cap', 'period', 'notes'];
  return [...box.querySelectorAll('.limreg-row')].map(row => {
    const r = {};
    keys.forEach(k => { const inp = row.querySelector(`[data-limreg="col${k[0].toUpperCase() + k.slice(1)}"]`); r[k] = inp ? inp.value.trim() : ''; });
    return r;
  }).filter(r => keys.some(k => r[k] !== ''));
}
async function limregSaveAll() {
  const rows = limregCollect();
  try {
    await setDoc(doc(db, 'app_settings', 'limits'), { rows, updatedAt: serverTimestamp(), updatedBy: auth.currentUser.uid }, { merge: true });
    LIMREG_ROWS = rows;
    toast(t('limreg.saved'));
  } catch {
    toast(t('limreg.error'), true);
  }
  limregPaint();
}

/* ---------- Sección «Límites de imágenes» (SISTEMA) ----------
   Punto 112 de la cola; orden de Ronald 2026-11-03 02:12 CST
   («Ok anexa el chequeo y revisión automática de esos límites
   en administración sistema»): el bloque pinta la ÚLTIMA
   medición automática del repositorio de imágenes de la
   Biblioteca (ronbo-store/ronbo-nutri-assets), guardada en
   app_settings/assets_usage — documento SOLO del propietario
   por su propio bloque de reglas —: tamaño contra el límite
   del sitio (1 GB, el del informe del punto 112), conteo de
   imágenes y fecha del chequeo, con su semáforo de criterios
   de PRODUCTO (verde por debajo del 70 % · ámbar del 70 al
   90 % · rojo por encima del 90 %). La medición corre FUERA de
   la app (la línea automática semanal, con la credencial del
   propietario): la app NO escribe este documento jamás, y sin
   documento pinta «Aún sin mediciones» — nunca un cero falso.
   El tráfico mensual de Pages no se puede medir de forma
   directa; la línea honesta va visible en el bloque
   (imglim.bandNote). */
const IMGLIM_LIMIT_BYTES = 1000000000;   // el «1 GB» del sitio, como lo declaró el informe del punto 112
let IMGLIM_DATA = null;   // null = aún no leído en esta sesión
function imglimState(pct) { return pct > 90 ? 'bad' : pct >= 70 ? 'warn' : 'ok'; }
function imglimFmt(bytes) {
  const gb = bytes / 1000000000;
  if (gb >= 1) return String(parseFloat(gb.toFixed(2))) + ' GB';
  return (bytes / 1000000).toFixed(1) + ' MB';
}
function imglimDateOf(v) {
  try {
    if (!v) return null;
    if (typeof v.toDate === 'function') return v.toDate();
    if (typeof v.seconds === 'number') return new Date(v.seconds * 1000);
    const d = new Date(v); return isNaN(d) ? null : d;
  } catch { return null; }
}
function admSecMountImgLim(body) {
  body.innerHTML = `<p class="progress-hint">${esc(t('imglim.hint'))}</p><div id="imglim-box"><div class="wempty">${esc(t('imglim.loading'))}</div></div>`;
  imglimLoad();
}
function admSecRefreshImgLim() { if (document.getElementById('imglim-box')) imglimLoad(); }
async function imglimLoad() {
  const box = document.getElementById('imglim-box');
  if (!box) return;
  if (!(IS_OWNER && ROLE === 'administrador')) { box.innerHTML = ''; return; }
  try {
    const s = await getDoc(doc(db, 'app_settings', 'assets_usage'));
    IMGLIM_DATA = s.exists() ? s.data() : null;
  } catch {
    toast(t('imglim.error'), true);
    if (!IMGLIM_DATA) { box.innerHTML = `<div class="wempty">${esc(t('imglim.error'))}</div>`; return; }
  }
  imglimPaint();
}
function imglimPaint() {
  const box = document.getElementById('imglim-box');
  if (!box) return;
  const d = IMGLIM_DATA;
  if (!d || typeof d.repoBytes !== 'number') { box.innerHTML = `<div class="wempty">${esc(t('imglim.none'))}</div>`; return; }
  const limit = typeof d.limitBytes === 'number' && d.limitBytes > 0 ? d.limitBytes : IMGLIM_LIMIT_BYTES;
  const pct = Math.round(d.repoBytes / limit * 1000) / 10;
  const st = imglimState(pct);
  const when = imglimDateOf(d.checkedAt);
  const loc = LANG === 'es' ? 'es' : 'en';
  const whenTxt = when ? when.toLocaleDateString(loc, { day: 'numeric', month: 'short', year: 'numeric' }) + ' · ' + when.toLocaleTimeString(loc, { hour: '2-digit', minute: '2-digit' }) : '—';
  box.innerHTML = `<div class="imglim-light imglim-${st}"><span class="imglim-dot" aria-hidden="true"></span><span>${esc(t('imglim.light.' + st))}</span><span class="imglim-pct">${pct} %</span></div>`
    + `<div class="imglim-track"><div class="imglim-fill imglim-${st}" style="width:${Math.min(100, pct)}%"></div></div>`
    + `<div class="imglim-rows">`
    + `<div class="imglim-row"><span class="muted">${esc(t('imglim.usedLab'))}</span><strong>${esc(imglimFmt(d.repoBytes))}</strong></div>`
    + `<div class="imglim-row"><span class="muted">${esc(t('imglim.limitLab'))}</span><strong>${esc(imglimFmt(limit))}</strong></div>`
    + `<div class="imglim-row"><span class="muted">${esc(t('imglim.imagesLab'))}</span><strong>${typeof d.imageCount === 'number' ? d.imageCount : '—'}</strong></div>`
    + `<div class="imglim-row"><span class="muted">${esc(t('imglim.checkedLab'))}</span><strong>${esc(whenTxt)}</strong></div>`
    + `</div>`
    + `<p class="progress-hint">${esc(t('imglim.thNote'))}</p>`
    + `<p class="progress-hint">${esc(t('imglim.bandNote'))}</p>`;
}

let DOS_PAINT_SEQ = 0;
async function renderDossierEditor() {
  const box = $('dossier-editor-box');
  if (!box) return;
  if (!(ROLE === 'entrenador' || IS_OWNER)) { box.style.display = 'none'; return; }
  box.style.display = '';
  const me = auth.currentUser.uid;
  /* HOTFIX 2026-10-24 (defecto cazado por Ronald en su iPhone: en
     «Mi perfil» solo se veía su tarjeta y «Cambiar foto»): la primera
     pintura del editor ya NO espera a la lectura de red de
     trainer_profiles/{me} — ese getDoc, primera lectura sin caché de
     la colección, podía no resolverse en su sesión y dejar la caja
     vacía. Ahora el formulario se pinta AL INSTANTE con el mejor
     dato local (MY_DOSSIER, ya cargado al entrar para el sistema de
     pendientes) y la lectura autoritativa hidrata en segundo plano:
     repinta solo si trae datos distintos y el formulario sigue sin
     tocar. Ante cualquier excepción al pintar se repinta vacío: el
     editor nunca puede quedar ausente para entrenador/administrador. */
  const seq = ++DOS_PAINT_SEQ;
  box.__dosDirty = false;
  box.oninput = () => { box.__dosDirty = true; };
  box.onchange = () => { box.__dosDirty = true; };
  const local = (typeof MY_DOSSIER !== 'undefined' && MY_DOSSIER) || {};
  try { dosPaintEditor(box, me, local); } catch { try { dosPaintEditor(box, me, {}); } catch {} }
  try {
    const s = await getDoc(doc(db, 'trainer_profiles', me));
    if (s.exists()) {
      const fresh = s.data();
      MY_DOSSIER = fresh;
      if (seq === DOS_PAINT_SEQ && !box.__dosDirty && box.__dosSig !== JSON.stringify(fresh)) {
        try { dosPaintEditor(box, me, fresh); } catch {}
      }
    }
  } catch {}
}

function dosPaintEditor(box, me, prof) {
  MY_DOSSIER = prof;
  box.__dosSig = JSON.stringify(prof || {});
  DOS_EDIT_PHOTO = undefined;
  const certs = Array.isArray(prof.certifications) && prof.certifications.length ? prof.certifications : [{}];
  const places = Array.isArray(prof.places) && prof.places.length ? prof.places : [{}];
  box.innerHTML = `
  <div class="panel dos-form">
    <h3 class="history-title">${esc(t('esc.dos.editTitle'))}</h3>
    <p class="progress-hint">${esc(t('esc.dos.editHint'))}</p>
    <label class="muted dos-field dos-field-static">${esc(t('esc.dos.photo'))}</label>
    ${prof.photoUrl ? `<img class="dos-photo-prev" id="dos-photo-prev" src="${esc(prof.photoUrl)}" alt="">` : `<img class="dos-photo-prev" id="dos-photo-prev" style="display:none" alt="">`}
    <div class="eval-actions"><button type="button" class="btn-ghost btn-sm" id="dos-photo-btn">${esc(t('esc.dos.photoUpload'))}</button>
    <input type="file" id="dos-photo-file" accept="image/*" style="display:none"></div>
    <label class="muted dos-field">${esc(t('esc.dos.headline'))}<input type="text" id="dos-headline" maxlength="120" value="${esc(prof.headline || '')}" placeholder="${esc(t('esc.dos.headlinePh'))}"></label>
    <label class="muted dos-field">${esc(t('esc.dos.aboutLabel'))}<textarea id="dos-about" rows="4" maxlength="2000">${esc(prof.about || '')}</textarea></label>
    <label class="muted dos-field">${esc(t('esc.dos.yearsLabel'))}<input type="number" id="dos-years" min="0" max="60" value="${prof.experienceYears || ''}"></label>
    <div class="muted dos-ctx-group"><span class="dos-ctx-title">${esc(t('esc.dos.contextsLabel'))}:</span><div class="dos-ctx-grid">${DOS_CONTEXTS.map(c => `<label class="dos-ctx-item"><input type="checkbox" class="dos-ctx" value="${c}" ${(Array.isArray(prof.contexts) && prof.contexts.includes(c)) ? 'checked' : ''}> ${esc(t('esc.dos.ctx.' + c))}</label>`).join('')}</div></div>
    <label class="muted dos-field">${esc(t('esc.dos.clientTypesLabel'))}<input type="text" id="dos-clienttypes" value="${esc((prof.clientTypes || []).join(', '))}"></label>
    <label class="muted dos-field">${esc(t('esc.dos.skillsLabel'))}<input type="text" id="dos-topskills" value="${esc((prof.topSkills || []).join(', '))}"></label>
    <div class="muted dos-section-title">${esc(t('esc.dos.certsLabel'))}</div>
    <p class="progress-hint">${esc(t('esc.dos.certsHint'))}</p>
    <div id="dos-certs">${certs.map(dosCertRowHTML).join('')}</div>
    <div class="eval-actions"><button type="button" class="btn-ghost btn-sm" id="dos-cert-add">${esc(t('esc.dos.addRow'))}</button></div>
    <label class="muted dos-field">${esc(t('esc.dos.specialtiesLabel'))}<input type="text" id="dos-specialties" value="${esc((prof.specialties || []).join(', '))}"></label>
    <label class="muted dos-field">${esc(t('esc.dos.notTrainsLabel'))}<input type="text" id="dos-nottrains" maxlength="300" value="${esc(prof.notTrains || '')}"></label>
    <label class="muted dos-field">${esc(t('esc.dos.languagesLabel'))}<input type="text" id="dos-languages" value="${esc((prof.languages || []).join(', '))}"></label>
    <div class="muted dos-section-title">${esc(t('esc.dos.placesLabel'))}</div>
    <p class="progress-hint">${esc(t('esc.dos.placesHint'))}</p>
    <div id="dos-places">${places.map(dosPlaceRowHTML).join('')}</div>
    <div class="eval-actions"><button type="button" class="btn-ghost btn-sm" id="dos-place-add">${esc(t('esc.dos.addRow'))}</button></div>
    <p class="progress-hint">${esc(t('esc.dos.adminNote'))}</p>
    <div class="eval-actions"><button type="button" class="btn-primary btn-sm" id="dos-save">${esc(t('form.save'))}</button>
    <button type="button" class="btn-ghost btn-sm" id="dos-preview">${esc(t('esc.dos.previewBtn'))}</button></div>
  </div>`;
  const wireDels = () => {
    document.querySelectorAll('#dos-certs .dc-del').forEach(b => b.onclick = () => { b.closest('.dos-cert-row').remove(); });
    document.querySelectorAll('#dos-places .dp-del').forEach(b => b.onclick = () => { b.closest('.dos-place-row').remove(); });
  };
  wireDels();
  $('dos-cert-add').onclick = () => { $('dos-certs').insertAdjacentHTML('beforeend', dosCertRowHTML({})); wireDels(); };
  $('dos-place-add').onclick = () => { $('dos-places').insertAdjacentHTML('beforeend', dosPlaceRowHTML({})); wireDels(); };
  $('dos-photo-btn').onclick = () => $('dos-photo-file').click();
  $('dos-photo-file').onchange = async e => {
    const f = e.target.files[0]; e.target.value = '';
    if (!f) return;
    try {
      DOS_EDIT_PHOTO = await dosCompressCover(f);
      const img = $('dos-photo-prev'); if (img) { img.src = DOS_EDIT_PHOTO; img.style.display = ''; }
    } catch {}
  };
  $('dos-preview').onclick = () => openDossierLive(me, 'preview');
  $('dos-save').onclick = async () => {
    await escEnsureTrainerScaffold(me, (UDATA && (UDATA.name || UDATA.email)) || '');
    const split = (id2, cap, itemCap) => ($(id2).value || '').split(',').map(s => s.trim().slice(0, itemCap)).filter(Boolean).slice(0, cap);
    const data = {
      headline: ($('dos-headline').value || '').trim().slice(0, 120),
      about: ($('dos-about').value || '').trim().slice(0, 2000),
      experienceYears: Math.max(0, Math.min(60, parseInt($('dos-years').value, 10) || 0)),
      contexts: [...document.querySelectorAll('.dos-ctx:checked')].map(x => x.value),
      clientTypes: split('dos-clienttypes', 6, 60),
      topSkills: split('dos-topskills', 3, 60),
      certifications: dosCollectCerts(),
      specialties: split('dos-specialties', 10, 40),
      notTrains: ($('dos-nottrains').value || '').trim().slice(0, 300),
      languages: split('dos-languages', 4, 30),
      places: dosCollectPlaces(),
      updatedAt: serverTimestamp()
    };
    if (DOS_EDIT_PHOTO !== undefined) data.photoUrl = DOS_EDIT_PHOTO;
    await setDoc(doc(db, 'trainer_profiles', me), data, { merge: true });
    MY_DOSSIER = { ...(MY_DOSSIER || {}), ...data };
    await auditLog('role', 'dossier.updated', me, '');
    toast(t('esc.modSaved'));
    /* Si la plantilla quedó completa, su pendiente se resuelve en
       el acto (el cómputo es local y puro). */
    try { renderPendings(); pendSyncDock(); } catch {}
    renderDossierEditor();
  };
}

/* Andamiaje del entrenador al asignarle el rol: perfil con las tres
   modalidades y contador en 0, y membresía «sin_membresia» (el nivel
   se solicita o lo concede el administrador). Idempotente. */
async function escEnsureTrainerScaffold(uid, name) {
  try {
    const ps = await getDoc(doc(db, 'trainer_profiles', uid));
    if (!ps.exists()) await setDoc(doc(db, 'trainer_profiles', uid), {
      displayName: name || '', modalities: [...ESC_MODALITIES], bio: '', available: true, activeStudents: 0, updatedAt: serverTimestamp(),
      /* Sello de cupo abierto (AUTH-042): nace SOLO cuando el perfil
         creado es el del propio propietario en sesión (la ruta de
         su dossier); al asignar el rol a OTRO, uid ≠ sesión y el
         perfil nace sin sello. */
      ...(uid === (auth.currentUser && auth.currentUser.uid) && IS_OWNER ? { quotaOpen: true } : {})
    });
    const ms = await getDoc(doc(db, 'memberships', uid));
    if (!ms.exists()) await setDoc(doc(db, 'memberships', uid), {
      level: null, status: 'sin_membresia', source: 'gratis', requestedLevel: null,
      requestedAt: null, decidedBy: null, decidedAt: null, startedAt: null, currentPeriodEnd: null, priceSnapshot: null
    });
  } catch {}
}

/* Sin metas por defecto (decisión de Ronald, 2026-10-20: «que nazcan
   sin metas hasta que el entrenador las fije»): la cuenta nace SIN
   campo goals y GOALS queda {} hasta que el entrenador las establece
   desde el editor de metas. goalOf(key) devuelve la meta de una
   métrica o null si no está fijada; hasAnyGoal() indica si hay alguna. */
let GOALS = {}; // metas del usuario en sesión; {} = sin metas fijadas
const METRICS = [
  { key: 'kcal', name: 'CALORÍAS',     icon: '🔥', color: '#22C55E', unit: 'kcal' },
  { key: 'prot', name: 'PROTEÍNA',      icon: '💪', color: '#3B82F6', unit: 'g' },
  { key: 'carb', name: 'CARBOHIDRATOS', icon: '🌾', color: '#F59E0B', unit: 'g' },
  { key: 'azuc', name: 'AZÚCARES',      icon: '🍬', color: '#A855F7', unit: 'g', max: true },
  { key: 'gras', name: 'GRASAS',        icon: '🫀', color: '#EF4444', unit: 'g' },
];
const MEAL_ORDER = { 'Desayuno': 1, 'Merienda': 2, 'Almuerzo': 3, 'Snack': 4, 'Cena': 5 };
const goalOf = key => { const v = Number(GOALS[key]); return (isFinite(v) && v > 0) ? v : null; };
const hasAnyGoal = () => METRICS.some(m => goalOf(m.key) !== null);

let MEALS = {};   // fecha -> [{id, meal, food, qty, kcal, prot, carb, sugar, fat, notes}]
let WEIGHTS = []; // [{id, date, weight, fat, muscle, notes}]
/* ================= I18N (English default, ES/EN toggle) ================= */
