/* F-07 (auditoría de cálculos 2026-11-06): las consultas «in»
   de Firestore admiten 30 valores; las listas de alumnos/clientes
   trocean TODOS los ids en bloques de 30 y fusionan los
   documentos, para que el alumno 31+ también cargue. */
function chunk30(ids) {
  const out = [];
  for (let i = 0; i < (ids || []).length; i += 30) out.push(ids.slice(i, i + 30));
  return out;
}
async function getDocsInChunks30(collName, field, ids) {
  const docs = [];
  for (const part of chunk30(ids)) {
    if (!part.length) continue;
    const s = await getDocs(query(collection(db, collName), where(field, 'in', part)));
    s.forEach(d => docs.push(d));
  }
  return docs;
}
async function loadClients() {
  const sec = $('clients-section');
  if (ROLE === 'usuario') { sec.style.display = 'none'; return; }
  sec.style.display = '';
  let users = [];
  try {
    /* El entrenador SOLO lista a sus asignados (consulta acotada por
       trainerUid — las reglas por documento no actúan de filtro:
       un listado sin acotar se denegaría entero); el administrador
       lista a todos. */
    const snap = ROLE === 'entrenador'
      ? await getDocs(query(collection(db, 'users'), where('trainerUid', '==', auth.currentUser.uid)))
      : await getDocs(collection(db, 'users'));
    snap.forEach(d => users.push({ id: d.id, ...d.data() }));
  } catch { users = []; }
  /* Alcance por rol: el administrador ve a todos; el entrenador,
     SOLO a sus clientes asignados (trainerUid == su uid). Los de
     en espera NO son del entrenador hasta que se le asignen. */
  const clients = users.filter(u => !u.isOwner && (ROLE === 'administrador' || u.trainerUid === auth.currentUser.uid));
  renderWaitingTray(users);
  renderApprovalsTray(users);
  let weights = []; let weightsOkC = true;
  try {
    const clientIds = clients.map(u => u.id);
    const ws = (ROLE === 'entrenador' && clientIds.length)
      ? await getDocsInChunks30('nutrition_weight', 'ownerUid', clientIds)
      : await getDocs(collection(db, 'nutrition_weight'));
    ws.forEach(d => { const v = d.data();
      if (v.ownerUid && num(v.weight) > 0) weights.push({ uid: v.ownerUid, date: v.date, weight: num(v.weight) }); });
  } catch { weightsOkC = false; }
  const lastByUid = {}, lastWByUid = {}, weightDatesByUid = {};
  weights.forEach(w => { if (!lastByUid[w.uid] || w.date > lastByUid[w.uid]) { lastByUid[w.uid] = w.date; lastWByUid[w.uid] = w.weight; } (weightDatesByUid[w.uid] = weightDatesByUid[w.uid] || []).push({ date: w.date, weight: w.weight }); });
  Object.values(weightDatesByUid).forEach(a => a.sort((x, y) => x.date < y.date ? -1 : 1));
  let pendingFood = {}; const foodItemsByUid = {}; let foodOkC = true;
  try {
    const clientIds2 = clients.map(u => u.id);
    const fs = (ROLE === 'entrenador' && clientIds2.length)
      ? await getDocsInChunks30('meal_help', 'ownerUid', clientIds2)
      : await getDocs(collection(db, 'meal_help'));
    fs.forEach(d => { const v = d.data();
      if (v.status === 'pending' && v.ownerUid) { pendingFood[v.ownerUid] = (pendingFood[v.ownerUid] || 0) + 1; (foodItemsByUid[v.ownerUid] = foodItemsByUid[v.ownerUid] || []).push({ id: d.id, createdAt: v.createdAt || null }); } });
  } catch { foodOkC = false; }
  /* Completitud de perfil por cliente (decisión de Ronald,
     2026-10-27): el % y lo que falta, derivados por
     clientProfileChecklist de las mismas fuentes que el checklist
     del alumno. Las solicitudes de comidas se leen UNA vez y
     acotadas: el administrador las lista todas; el entrenador,
     solo las dirigidas a él (la consulta que las reglas prueban). */
  let mealReqsAll = []; let reqOkC = true;
  try {
    const mq = ROLE === 'entrenador'
      ? await getDocs(query(collection(db, 'meal_requests'), where('trainerUid', '==', auth.currentUser.uid)))
      : await getDocs(collection(db, 'meal_requests'));
    mq.forEach(d => mealReqsAll.push({ id: d.id, ...d.data() }));
  } catch { reqOkC = false; }
  /* PETICIONES (AUTH-2026-11-04-237): la misma lectura acotada
     que las solicitudes de comidas (el entrenador, solo las
     dirigidas a él; el administrador, todas); solo las ABIERTAS
     alimentan la unión de pendientes. */
  const treqOpenByUidC = {}; let treqOkC = true;
  try {
    const tq = ROLE === 'entrenador'
      ? await getDocs(query(collection(db, 'trainer_requests'), where('trainerUid', '==', auth.currentUser.uid)))
      : await getDocs(collection(db, 'trainer_requests'));
    tq.forEach(d => { const v = d.data();
      if (v && v.status === 'sent' && v.studentUid) (treqOpenByUidC[v.studentUid] = treqOpenByUidC[v.studentUid] || []).push({ id: d.id, type: v.type, days: (v.days != null ? v.days : null), createdISO: v.createdISO || null }); });
  } catch { treqOkC = false; }
  /* RETOS (AUTH-2026-11-08-307): las solicitudes de reto SIN
     DECIDIR de los clientes de esta pasada, con la misma
     disciplina (chalOkC entra en sharedOkC). Se leen acotadas por
     los uid de la pasada: la regla de lectura de participaciones
     es por documento (el alumno, su entrenador asignado, el
     creador del reto, el propietario). */
  const chalOpenByUidC = {}; let chalOkC = true;
  try {
    const cids = clients.map(u => u.id);
    const pendC = [];
    for (let i = 0; i < cids.length; i += 30) {
      const ps = await getDocs(query(collection(db, 'challenge_parts'), where('uid', 'in', cids.slice(i, i + 30))));
      ps.forEach(d => { const v = d.data();
        if (v && v.joinState === 'pending') pendC.push({ id: d.id, uid: v.uid, challengeId: v.challengeId, ms: treqMs(v.joinRequestedAt) }); });
    }
    await Promise.all(pendC.map(async p => {
      let name = '';
      try { const cs = await getDoc(doc(db, 'challenges', p.challengeId)); if (cs.exists()) name = chalNameOf({ id: cs.id, ...cs.data() }); } catch {}
      (chalOpenByUidC[p.uid] = chalOpenByUidC[p.uid] || []).push({ id: p.id, chalName: name, createdISO: p.ms ? pendISOof(new Date(p.ms)) : null });
    }));
  } catch { chalOkC = false; }
  const reqMs = x => (x && x.requestedAt && x.requestedAt.toMillis) ? x.requestedAt.toMillis() : 0;
  const latestReqByUid = {};
  mealReqsAll.forEach(r => { if (r.alumnoUid && (!latestReqByUid[r.alumnoUid] || reqMs(r) >= reqMs(latestReqByUid[r.alumnoUid]))) latestReqByUid[r.alumnoUid] = r; });
  const chkByUid = {};
  await Promise.all(clients.map(async u => { try { chkByUid[u.id] = await clientProfileChecklist(u, latestReqByUid[u.id] || null); } catch {} }));
  /* Alertas vigentes por cliente (pedido de Ronald, 2026-10-27):
     las mismas derivadas al render que alimentan sus Pendientes y
     la ficha — la tarjeta las muestra bajo la completitud. */
  const alertsByUid = {};
  await Promise.all(clients.map(async u => { try { alertsByUid[u.id] = await trainerAlertsFor(u.id, u); } catch {} }));
  /* AUTH-110: LA UNIÓN ÚNICA también en esta pasada (trainerPendUnion,
     la misma función que consume «Mis alumnos»): pendientes del
     entrenador idénticos ítem a ítem en ambas vistas. Las lecturas
     por cliente (pendconfig, pendstate, su nutrition_progress) son
     las formas ya vivas de la pasada de Alumnos y de la ficha; las
     reglas vivas las permiten al propietario y al entrenador
     asignado (preflight contra 15e87534: delta CERO). Un fallo de
     lectura compartida o del propio cliente marca SOLO a ese
     cliente en error — jamás un «al día» falso. */
  const tpendByUid = {}, tpendErrByUid = {};
  const sharedOkC = weightsOkC && foodOkC && reqOkC && treqOkC && chalOkC;
  await Promise.all(clients.map(async u => {
    if (!sharedOkC || !chkByUid[u.id]) { tpendErrByUid[u.id] = true; return; }
    try {
      const cs = await getDoc(doc(db, 'nutrition_progress', u.id + '_pendconfig'));
      const cfg = cs.exists() ? Object.assign(pendDefaults(), cs.data()) : null;
      const ss = await getDoc(doc(db, 'nutrition_progress', u.id + '_pendstate'));
      const marks = ss.exists() ? ((ss.data() && ss.data().marks) || {}) : {};
      const ps = await getDocs(query(collection(db, 'nutrition_progress'), where('ownerUid', '==', u.id)));
      let bodyItem = studentsBodyItem(u, null);
      if (btModuleOn(u) && btIsActive(u)) {
        const bs = await getDocs(query(collection(db, 'body_type_estimates'), where('clientUid', '==', u.id)));
        bodyItem = studentsBodyItem(u, bs.size);
      }
      tpendByUid[u.id] = trainerPendUnion(chkByUid[u.id], studentsPendCompute({
        cfg, marks,
        wdates: weightDatesByUid[u.id] || [],
        prog: spProgParse(ps),
        reqLatest: latestReqByUid[u.id] || null,
        foodItems: foodItemsByUid[u.id] || [],
        trainReqs: treqOpenByUidC[u.id] || [],
        chalReqs: chalOpenByUidC[u.id] || []
      }, new Date()), bodyItem, u);
    } catch { tpendErrByUid[u.id] = true; }
  }));
  /* ORGANIZAR CLIENTES (AUTH-2026-10-28-066): «tiene plan activo»
     por cliente, propagado de la MISMA lectura que ya hizo
     trainerAlertsFetch dentro de trainerAlertsFor (su caché de
     30 s) — cero consultas nuevas. La pasada entera queda en
     CLIENTS_LAST y la pintan la rejilla o la lista según el
     conmutador, sin re-derivar nada al cambiar de vista. */
  const planByUid = {};
  clients.forEach(u => { const c = TALERTS_CACHE[u.id]; planByUid[u.id] = !!(c && c.hasPlan); });
  /* ASIGNACIONES (este paquete): el coach vigente de cada cliente
     (nutritionist_relations con status 'activa') para pintar la
     línea «🏋️ entrenador · 🥗 coach» de cada fila. El administrador
     lo lee en UNA pasada de colección (la misma que ya hace su
     consola del módulo); el entrenador, por cliente y en silencio
     si las reglas no se lo dan — sin lectura no hay línea de coach
     (clave ausente = desconocido, jamás un «sin coach» falso). Los
     nombres se siembran desde la propia lista de usuarios y lo que
     falte lo resuelve assignResolveName una sola vez por uid. */
  const coachByUid = {};
  if (ROLE === 'administrador') {
    try {
      const ns = await getDocs(collection(db, 'nutritionist_relations'));
      ns.forEach(d => { const v = d.data(); coachByUid[d.id] = (v.status === 'activa' && v.nutritionistUid) ? v.nutritionistUid : null; });
      clients.forEach(u => { if (!(u.id in coachByUid)) coachByUid[u.id] = null; });
    } catch { /* desconocido: sin claves */ }
  } else {
    await Promise.all(clients.map(async u => {
      try { const s = await getDoc(doc(db, 'nutritionist_relations', u.id)); coachByUid[u.id] = (s.exists() && s.data().status === 'activa') ? (s.data().nutritionistUid || null) : null; } catch {}
    }));
  }
  users.forEach(u => { if (u.name && !ASSIGN_NAMES[u.id]) ASSIGN_NAMES[u.id] = u.name; });
  const namePend = new Set();
  clients.forEach(u => { if (u.trainerUid) namePend.add(u.trainerUid); const cv = coachByUid[u.id]; if (cv) namePend.add(cv); });
  await Promise.all([...namePend].map(uid => assignNameSync(uid) ? null : assignResolveName(uid)));
  CLIENTS_LAST = { clients, chkByUid, alertsByUid, planByUid, lastByUid, lastWByUid, pendingFood, tpendByUid, tpendErrByUid, reqByUid: latestReqByUid, coachByUid, allUsers: users };
  renderClientsViewbar();
  renderClientsBody();
  $('client-detail').style.display = 'none'; $('client-detail').innerHTML = '';
  /* Roles+Escalabilidad: caché de nombres para las bandejas nuevas y
     los paneles del entrenador (membresía y solicitudes de comidas). */
  users.forEach(u => { ADMIN_NAME_CACHE[u.id] = u.name || u.email || ''; });
  try { trainerAlertsRender(); } catch {}
  renderMembershipBox();
  renderMealTrainerBox();
  renderModalityTrainerBox();
  /* El editor del dossier YA NO vive en esta pestaña (perfil-visible,
     2026-10-24): se mudó a «Mi perfil» y lo pinta renderProfileView.
     MY_DOSSIER para los pendientes se carga en loadRolesX, no aquí. */
}
