  fl.style.display = '';
  const x = $('pendlist-x'); if (x) x.onclick = () => pendListClose();
  const cx = $('pendlist-cancel'); if (cx) cx.onclick = () => pendListClose();
  const sb = $('pendlist-send'); if (sb) sb.onclick = () => pendListSend();
  pendListRenderPreview();
