  return ((aiState && aiState.r1 && aiState.r1.foods) || []).map(f => { const d = aiFoodFromIdentify(f); return { name: d.name, grams: num(d.grams), unit: d.unit, pieces: d.pieces, perPiece: d.perPiece, qsrc: f.quantitySource || null }; });
