    <div class="pl-auto-lab"><span>${esc(t('train.auto.eqLabel'))}</span><div class="pl-auto-chips"><button type="button" class="pl-type-btn pl-auto-eqall is-on">${esc(t('train.auto.eq.all'))}</button>${eqChips}</div></div>
