  if (eqAll) eqAll.onclick = () => { const on = !eqAll.classList.contains('is-on'); eqAll.classList.toggle('is-on', on); body.querySelectorAll('.pl-auto-eq').forEach(x => x.classList.toggle('is-on', on)); };
