  ciclismo:           { suave: 4.0,  moderada: 8.0,  intensa: 10.0 }, // suave corregido (antes 6)
  natacion:           { suave: 6.0,  moderada: 8.0,  intensa: 10.0 },
  futbol:             { suave: 7.0,  moderada: 9.0,  intensa: 10.0 },
