{ const mf = $('m-food'); if (mf) mf.addEventListener('input', () => { if (MEAL_PICK && mf.value.trim() !== MEAL_PICK.name) mealPickClear(); }); }
acWire($('m-desc'), $('ac-sug-desc'), 'desc');
acWire($('food-text-desc'), $('ac-sug-text'), 'desc');

/* ============ BIBLIOTECA COMUNITARIA DE ALIMENTOS (2026-10-30) ============
   Diseño: DISENO-BIBLIOTECA-ALIMENTOS-COMUNIDAD-2026-10-30.md.
   Decisiones de Ronald P1-P5 (chat, 2026-10-30 18:26-18:31 CDT) y su
   «aprobado y ejecútalo» (correo 18:13 CDT). DOS colecciones:
   food_library — la ficha pública SANEADA: sin autor, sin fecha, sin
   procedencia (no «ocultos»: no existen en el dato, y la lista
   cerrada de las reglas hace imposible escribirlos);
   food_contrib — la antesala privada (aportes y reportes): la leen
   solo su autor y los curadores (administrador y entrenadores, P3).
   Entrada SOLO por opt-in expreso por alimento (P1); también valen
   fichas nacidas de IA (P4) y la marca puede ir en el nombre (P5):
   el filtro es el motor de posibles errores + la curaduría. Adoptar
   una ficha rellena el formulario por acApply (con su reescalado
   AUTH-089) y al guardar escribe un nutrition_meals propio y normal
   por la cláusula de siempre: la biblioteca es el arranque y el
   historial personal toma el relevo.
   CORRECCIÓN DE RONALD (2026-10-31, AUTH-110) — dos decisiones de
   arriba quedan corregidas por su palabra de hoy: P1 (entrada solo
   por opt-in expreso) queda SIN EFECTO: «Todo pasa a mi bandeja de
   aprobación» — cada alimento guardado genera AUTOMÁTICAMENTE su
   candidato en la antesala, sin pregunta ni toque de compartir; y
   P3 (curan administrador y entrenadores) queda corregida a
   curaduría SOLO del administrador: la bandeja y la administración
   del catálogo viven en Administración (sección desplegable
   «foodlib» de ADMIN_SECTIONS), y la ventana «Alimentos de la
   comunidad» de Inicio y el botón manual duplicado bajo el diario
   desaparecen de la vista de las personas. La búsqueda sigue
   mezclando el catálogo aprobado (sin marca de «comunidad» en
   Inicio) y food_library sigue anónima por estructura. */
const foodlibSugCache = new Map(); // prefijo normalizado -> filas públicas de la sesión
const foodlibRows = new Map();     // id -> ficha pública pintada en la ventana
let foodlibLastKey = null, foodlibQuery = '', foodlibIsOpen = false;
let FL_TRAY_EL = null, FL_LIST_EL = null, FL_MORE_EL = null; // anfitriones DOM en Administración

/* CORRECCIÓN DE P3 (Ronald, 2026-10-31): curador = SOLO el
   administrador («solamente yo, nadie más»). Los entrenadores ya no
   curan: ni en la UI (esta puerta) ni en las reglas (isCuratorUser
   pasó a isAdminUser en el mismo paquete). */
function foodlibCurator() { return ROLE === 'administrador'; }
function foodlibQtyText(f) {
  return f.qtyUnit === 'unidad'
    ? `${acNum(f.qtyNum)} unidad (${acNum(num(f.qtyNum) * num(f.pieceGrams))} g)`
    : `${acNum(f.qtyNum)} ${f.qtyUnit}`;
}
function foodlibEntry(f) {
  return { key: f.nameKey || acNorm(f.name), name: f.name, qty: foodlibQtyText(f),
    kcal: num(f.kcal), prot: num(f.prot), carb: num(f.carb), sugar: num(f.sugar), fat: num(f.fat), fiber: fiberOf(f) };
}
function foodlibBaseOf(v) { return v.qtyUnit === 'unidad' ? num(v.qtyNum) * num(v.pieceGrams) : num(v.qtyNum); }
function foodlibReasonText(code) { return t('foodlib.reason.' + (code === 'no-unico' ? 'nounico' : code)); }
/* MOTOR DE POSIBLES ERRORES (diseño §2.2): rechazos duros (no entra
   ni a la antesala) y señales blandas que viajan como flags para la
   curaduría. Las mismas guardias duras viven en las reglas: lo que
   aquí se detecta, el servidor lo exige. */
function foodlibValidate(v) {
  const hard = [], soft = [];
  const name = String(v.name || '').trim();
  if (name.length < 2 || name.length > 80) hard.push('name');
  if (/@|https?:|www\./i.test(name) || /\d{7,}/.test(name)) hard.push('personal');
  if (!(num(v.qtyNum) > 0)) hard.push('qty');
  if (!['g', 'ml', 'unidad'].includes(v.qtyUnit)) hard.push('unit');
  if (v.qtyUnit === 'unidad' && !(num(v.pieceGrams) >= 5 && num(v.pieceGrams) <= 500)) hard.push('piece');
  for (const k of ['kcal', 'prot', 'carb', 'sugar', 'fat']) if (!(num(v[k]) >= 0)) hard.push('neg');
  /* FIBRA (Fase 1): opcional — ausente (null) no es error ni cero;
     presente exige la guarda de no-negatividad de siempre. */
  if (v.fiber != null && !(num(v.fiber) >= 0)) hard.push('neg');
  const base = foodlibBaseOf(v);
  if (base > 0) {
    if (num(v.kcal) * 100 > 950 * base) hard.push('density');
    for (const k of ['prot', 'carb', 'sugar', 'fat']) if (num(v[k]) * 100 > 100 * base) hard.push('density');
    if (v.fiber != null && num(v.fiber) * 100 > 100 * base) hard.push('density');
    if (num(v.sugar) > num(v.carb) + 1) hard.push('sugar');
    /* FIBRA (Fase 1): espejo de la guarda de las reglas — la fibra
       es parte de los carbohidratos; más fibra que carbos (+1 de
       tolerancia, como el azúcar) no entra. */
    if (v.fiber != null && num(v.fiber) > num(v.carb) + 1) hard.push('fiber');
    const atw = 4 * num(v.prot) + 4 * num(v.carb) + 9 * num(v.fat);
    if (num(v.kcal) > 0 && Math.abs(atw - num(v.kcal)) > 0.30 * num(v.kcal)) soft.push('atwater');
    if (num(v.kcal) * 100 > 700 * base) soft.push('densityHigh');
    if (/,/.test(name) || / con /i.test(name)) soft.push('compound');
  }
  return { hard: [...new Set(hard)], soft: [...new Set(soft)] };
}
function foodlibFlagsText(flags) {
  const map = { atwater: 'foodlib.flag.atwater', densityHigh: 'foodlib.flag.densityHigh', compound: 'foodlib.flag.compound', dupDiverge: 'foodlib.flag.dupDiverge' };
  return (flags || []).filter(f => map[f]).map(f => t(map[f])).join(' · ');
}
/* Segunda fuente del buscador de alimentos (ver acWire): prefijo
   sobre nameKey, acotada por limit(12) y cacheada por prefijo en la
   sesión; excluye TODO lo que ya vive en el historial propio. */
async function foodlibSearch(q, n) {
  const own = new Set(acIndex().map(e => e.key));
  let rows = foodlibSugCache.get(q);
  if (!rows) {
    const snap = await getDocs(query(collection(db, 'food_library'),
      where('nameKey', '>=', q), where('nameKey', '<', q + '\uf8ff'), limit(12)));
    rows = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    foodlibSugCache.set(q, rows);
  }
  return rows.filter(f => !own.has(f.nameKey)).slice(0, n);
}
/* Deriva la cantidad de referencia de la ficha desde el qty TEXTUAL
   del registro guardado, con el parser vivo de «Repetir»: gramos y
   ml directos; piezas -> 'unidad' con los gramos por pieza del
   paréntesis «(100 g)» cuando el registro lo trae. Lo no convertible
   (taza, plato, texto libre) deja la cantidad vacía y la hoja la
   pide: el par cantidad<->valores nunca nace descuadrado. */
function foodlibFromMeal(m) {
  const v = { name: String((m && m.food) || '').trim(), kcal: num(m && m.kcal), prot: num(m && m.prot),
    carb: num(m && m.carb), sugar: num(m && m.sugar), fat: num(m && m.fat), fiber: fiberOf(m),
    qtyNum: NaN, qtyUnit: 'g', pieceGrams: NaN };
  const p = repeatParseQty((m && m.qty) || '');
  if (p) {
    if (p.pieces) {
      v.qtyNum = p.num; v.qtyUnit = 'unidad';
      const tot = String((m && m.qty) || '').match(/\((\d+(?:\.\d+)?)\s*g\)/);
      if (tot && p.num > 0) v.pieceGrams = Math.round((parseFloat(tot[1]) / p.num) * 10) / 10;
    } else if (/^(g|gr|gramos?)$/.test(p.unit) || p.unit === '') { v.qtyNum = p.num; v.qtyUnit = 'g'; }
    else if (p.unit === 'ml') { v.qtyNum = p.num; v.qtyUnit = 'ml'; }
  }
  return v;
}
/* ---------- CANDIDATO AUTOMÁTICO (corrección de P1) ----------
   Ronald, 2026-10-31: «Todo pasa a mi bandeja de aprobación». Cada
   alimento que la persona guarda (manual o nacido de IA, P4) genera
   AUTOMÁTICAMENTE su candidato en la antesala food_contrib — sin
   pregunta, sin botón de compartir, sin superficie alguna para la
   persona. Los motores de siempre apoyan la aprobación: validación
   dura (lo imposible o con pinta de dato personal NO sale nunca),
   anti-duplicados (si ya está en la biblioteca con la misma unidad
   y valores cercanos, no se duplica la bandeja; si un pendiente
   propio con la misma clave ya espera, tampoco) y señales blandas
   como flags. Es SILENCIOSO y jamás bloquea el guardado: cualquier
   fallo se traga. Solo corre para el propio registro del dueño
   (ownerUid == yo); lo que un entrenador anota por un alumno no
   genera candidato en este paquete. La ficha pública que nazca de
   su aprobación sigue anónima por estructura (P2/P5 intactos).
   REACTIVACIÓN (AUTH-2026-10-31-116): la captación estuvo
   SUSPENDIDA por AUTH-114 (correo de Ronald, 590, 2026-10-31
   13:21 CDT: «privacidad de alimentos prioridad 1 con suspensión
   de captación automática hasta resolver aviso al usuario») hasta
   que Ronald aprobara el aviso al usuario. El aviso quedó APROBADO
   por Ronald (chat, 2026-10-31 14:19 CDT: «Apruebo el aviso») y
   PUBLICADO en la página de privacidad en este mismo paquete; la
   guarda FOODLIB_CAPTURE_SUSPENDED se retira y los dos ganchos de
   guardado vuelven a llamar a esta función — el comportamiento es
   el verificado de AUTH-113. */
async function foodlibAutoCandidate(m) {
  try {
    if (!auth.currentUser || !m || m.ownerUid !== auth.currentUser.uid) return;
    const v = foodlibFromMeal(m);
    const errs = foodlibValidate(v);
    if (errs.hard.length) return; // incluye 'personal': ese nombre jamás sale
    v.nameKey = acNorm(v.name);
    const flags = [...errs.soft];
    const dupSnap = await getDocs(query(collection(db, 'food_library'), where('nameKey', '==', v.nameKey), limit(5)));
    for (const d of dupSnap.docs) {
      const f = d.data();
      if (num(f.kcal) > 0 && Math.abs(num(f.kcal) - v.kcal) > 0.25 * num(f.kcal)) flags.push('dupDiverge');
      else if (f.qtyUnit === v.qtyUnit) return; // ya vive en la biblioteca
    }
    const uid = auth.currentUser.uid;
    const mineSnap = await getDocs(query(collection(db, 'food_contrib'), where('contributorUid', '==', uid)));
    if (mineSnap.docs.some(d => { const a = d.data(); return a.kind === 'aporte' && a.estado === 'pendiente' && a.nameKey === v.nameKey; })) return;
    const data = { kind: 'aporte', name: v.name, nameKey: v.nameKey, qtyNum: v.qtyNum, qtyUnit: v.qtyUnit,
      kcal: v.kcal, prot: v.prot, carb: v.carb, sugar: v.sugar, fat: v.fat,
      flags: [...new Set(flags)], contributorUid: uid,
      contributorName: (typeof UDATA !== 'undefined' && UDATA && (UDATA.name || UDATA.email)) || '',
      estado: 'pendiente', createdAt: serverTimestamp() };
    if (v.qtyUnit === 'unidad') data.pieceGrams = v.pieceGrams;
    /* FIBRA (Fase 1): el candidato la lleva solo si el registro la
       traía — la ficha pública que nazca de su aprobación la tendrá
       o no la tendrá, como el registro de origen. */
    if (v.fiber != null) data.fiber = v.fiber;
    await addDoc(collection(db, 'food_contrib'), data);
  } catch {}
}
/* ---------- Catálogo publicado: filas de Administración ----------
   La lista de fichas vivas (con su corrección y su retirada, solo
   curador) se pinta SOLO dentro de la sección de Administración;
   foodlibRowHTML/foodlibWireRows no conocen otro anfitrión. El
   «Usar» de cada fila sigue adoptando la ficha en el formulario
   (es el arranque de búsqueda, intacto). */
function foodlibRowHTML(f) {
  const e = foodlibEntry(f);
  return `<div class="foodlib-row" data-fl-row="${f.id}">
    <div class="foodlib-row-main"><span class="sg-name">${esc(f.name)}</span><span class="sg-meta">${esc(acMeta(e))}</span></div>
    <div class="foodlib-row-btns">
      <button type="button" class="btn-primary btn-sm" data-fl-use="${f.id}">${esc(t('foodlib.use'))}</button>
      <button type="button" class="btn-ghost btn-sm" data-fl-report="${f.id}">${esc(t('foodlib.report'))}</button>
      ${foodlibCurator() ? `<button type="button" class="btn-ghost btn-sm" data-fl-edit="${f.id}">${esc(t('foodlib.edit'))}</button><button type="button" class="btn-ghost btn-sm" data-fl-remove="${f.id}">${esc(t('foodlib.removeLib'))}</button>` : ''}
    </div>
    <div class="foodlib-row-sub" id="fl-sub-${f.id}"></div>
  </div>`;
}
function foodlibWireRows(scope) {
  scope.querySelectorAll('[data-fl-use]').forEach(b => b.onclick = () => {
    const f = foodlibRows.get(b.dataset.flUse); if (!f) return;
    MEAL_FORM_MANUAL_NEW = false; // AUTH-287: apertura directa — la zona de IA del formulario es la única puerta ahí
    aiOpenMealModal();
    acApply($('m-food'), foodlibEntry(f), 'food');
  });
  scope.querySelectorAll('[data-fl-report]').forEach(b => b.onclick = () => foodlibReportOpen(b.dataset.flReport));
  scope.querySelectorAll('[data-fl-edit]').forEach(b => b.onclick = () => foodlibEditOpen(b.dataset.flEdit));
  scope.querySelectorAll('[data-fl-remove]').forEach(b => b.onclick = async () => {
    if (!confirm(t('foodlib.removeConfirm'))) return;
    try {
      await deleteDoc(doc(db, 'food_library', b.dataset.flRemove));
      foodlibSugCache.clear(); foodlibRows.delete(b.dataset.flRemove);
      toast(t('foodlib.removedLib'));
      foodlibLoadList(true);
    } catch { toast(t('foodlib.errHard'), true); }
  });
}
async function foodlibLoadList(reset) {
  const list = FL_LIST_EL; if (!list) return;
  if (reset) { foodlibLastKey = null; list.innerHTML = ''; foodlibRows.clear(); }
  const conds = [];
  if (foodlibQuery) { conds.push(where('nameKey', '>=', foodlibQuery), where('nameKey', '<', foodlibQuery + '\uf8ff')); }
  else conds.push(where('nameKey', '>=', ''));
  if (foodlibLastKey) conds.push(where('nameKey', '>', foodlibLastKey));
  conds.push(limit(51));
  let docs = [];
  try {
    const snap = await getDocs(query(collection(db, 'food_library'), ...conds));
    docs = snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch { if (reset) list.innerHTML = `<p class="wempty">${esc(t('foodlib.empty'))}</p>`; return; }
  const page = docs.slice(0, 50);
  if (docs.length) foodlibLastKey = docs[Math.min(49, docs.length - 1)].nameKey;
  const more = FL_MORE_EL; if (more) more.style.display = docs.length > 50 ? '' : 'none';
  if (reset && !page.length) { list.innerHTML = `<p class="wempty">${esc(t('foodlib.empty'))}</p>`; return; }
  for (const f of page) foodlibRows.set(f.id, f);
  list.insertAdjacentHTML('beforeend', page.map(f => foodlibRowHTML(f)).join(''));
  foodlibWireRows(list);
}
function foodlibReportOpen(id) {
  const f = foodlibRows.get(id); const sub = $('fl-sub-' + id); if (!f || !sub) return;
  sub.innerHTML = `<label>${esc(t('foodlib.reportReason'))} <select id="fl-rep-reason-${id}">${['valores', 'duplicado', 'nombre', 'otro'].map(r => `<option value="${r}">${esc(foodlibReasonText(r))}</option>`).join('')}</select></label> <button type="button" class="btn-primary btn-sm" id="fl-rep-send-${id}">${esc(t('foodlib.reportSend'))}</button>`;
  $('fl-rep-send-' + id).onclick = async () => {
    try {
      await addDoc(collection(db, 'food_contrib'), { kind: 'reporte', publicId: id, foodName: f.name,
        reason: $('fl-rep-reason-' + id).value, reporterUid: auth.currentUser.uid, estado: 'pendiente', createdAt: serverTimestamp() });
      sub.innerHTML = '';
      toast(t('foodlib.reportSent'));
    } catch { toast(t('foodlib.errHard'), true); }
  };
}
function foodlibValFieldsHTML(prefix, v) {
  return `<label>${esc(t('form.food'))} <input type="text" data-vf="name" value="${esc(v.name || '')}" maxlength="80"></label>
    <div class="frow3">
      <label>${esc(t('form.amount'))} <input type="number" data-vf="qtyNum" step="any" value="${v.qtyNum != null && Number.isFinite(num(v.qtyNum)) ? v.qtyNum : ''}"></label>
      <label>${esc(t('foodlib.f.unit'))} <select data-vf="qtyUnit">${['g', 'ml', 'unidad'].map(u => `<option value="${u}"${v.qtyUnit === u ? ' selected' : ''}>${esc(t('foodlib.unit.' + u))}</option>`).join('')}</select></label>
      <label data-vf-piece style="${v.qtyUnit === 'unidad' ? '' : 'display:none'}">${esc(t('foodlib.f.piece'))} <input type="number" data-vf="pieceGrams" step="any" value="${v.pieceGrams != null && Number.isFinite(num(v.pieceGrams)) ? v.pieceGrams : ''}"></label>
    </div>
    <div class="frow3">
      <label>${esc(t('form.kcal'))} <input type="number" data-vf="kcal" step="any" value="${v.kcal != null ? v.kcal : ''}"></label>
      <label>${esc(t('form.protein'))} <input type="number" data-vf="prot" step="any" value="${v.prot != null ? v.prot : ''}"></label>
      <label>${esc(t('form.carbs'))} <input type="number" data-vf="carb" step="any" value="${v.carb != null ? v.carb : ''}"></label>
    </div>
    <div class="frow3">
      <label>${esc(t('form.sugar'))} <input type="number" data-vf="sugar" step="any" value="${v.sugar != null ? v.sugar : ''}"></label>
      <label>${esc(t('form.fat'))} <input type="number" data-vf="fat" step="any" value="${v.fat != null ? v.fat : ''}"></label>
      <label>${esc(t('form.fiber'))} <input type="number" data-vf="fiber" step="any" value="${v.fiber != null ? v.fiber : ''}"></label>
    </div>`;
}
function foodlibValsFrom(scope) {
  const g = k => { const el = scope.querySelector(`[data-vf="${k}"]`); return el ? el.value : ''; };
  const fibRaw = g('fiber');
  return { name: String(g('name')).trim(), qtyNum: num(g('qtyNum')), qtyUnit: g('qtyUnit'),
    pieceGrams: num(g('pieceGrams')), kcal: num(g('kcal')), prot: num(g('prot')),
    carb: num(g('carb')), sugar: num(g('sugar')), fat: num(g('fat')),
    /* FIBRA (Fase 1): campo vacío = la ficha queda SIN el dato
       (null), nunca un 0 inventado. */
    fiber: String(fibRaw).trim() === '' ? null : num(fibRaw) };
}
function foodlibCleanFicha(v) {
  const ficha = { name: v.name, nameKey: acNorm(v.name), qtyNum: v.qtyNum, qtyUnit: v.qtyUnit,
    kcal: v.kcal, prot: v.prot, carb: v.carb, sugar: v.sugar, fat: v.fat };
  if (v.fiber != null) ficha.fiber = v.fiber;
  if (v.qtyUnit === 'unidad') ficha.pieceGrams = v.pieceGrams;
  return ficha;
}
/* Corrección curada de una ficha pública (diseño §2.5): lo que se
   publica es la versión corregida; las copias ya adoptadas son el
   diario de cada quien y NO se reescriben. */
function foodlibEditOpen(id) {
  const f = foodlibRows.get(id); const sub = $('fl-sub-' + id); if (!f || !sub) return;
  sub.innerHTML = foodlibValFieldsHTML('lib', f) + `<button type="button" class="btn-primary btn-sm" id="fl-edit-save-${id}">${esc(t('foodlib.editSave'))}</button>`;
  const unitSel = sub.querySelector('[data-vf="qtyUnit"]');
  if (unitSel) unitSel.onchange = () => { const w = sub.querySelector('[data-vf-piece]'); if (w) w.style.display = unitSel.value === 'unidad' ? '' : 'none'; };
  $('fl-edit-save-' + id).onclick = async () => {
    const v = foodlibValsFrom(sub);
    if (foodlibValidate(v).hard.length) { toast(t('foodlib.errHard'), true); return; }
    const ficha = foodlibCleanFicha(v);
    const upd = { ...ficha };
    if (ficha.qtyUnit !== 'unidad') upd.pieceGrams = deleteField();
    /* FIBRA (Fase 1): si el curador la borra del campo, la ficha la
       pierde de verdad (merge no borra claves ausentes). */
    if (v.fiber == null) upd.fiber = deleteField();
    try {
      await setDoc(doc(db, 'food_library', id), upd, { merge: true });
      foodlibSugCache.clear();
      toast(t('foodlib.correctionSaved'));
      foodlibLoadList(true);
    } catch { toast(t('foodlib.errHard'), true); }
  };
}
/* ---------- Bandeja de aprobación (SOLO el administrador) ---------- */
async function foodlibLoadTray() {
  const sub = FL_TRAY_EL; if (!sub) return;
  let docs = [];
  try {
    const snap = await getDocs(query(collection(db, 'food_contrib'), where('estado', '==', 'pendiente')));
    docs = snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch {}
  const aportes = docs.filter(d => d.kind === 'aporte');
  const reportes = docs.filter(d => d.kind === 'reporte');
  if (!docs.length) { sub.innerHTML = `<h4>${esc(t('foodlib.trayBtn'))}</h4><p class="wempty">${esc(t('foodlib.trayEmpty'))}</p>`; return; }
  sub.innerHTML = `<h4>${esc(t('foodlib.trayBtn'))} (${docs.length})</h4>` +
    aportes.map(a => { const flags = foodlibFlagsText(a.flags); return `<div class="foodlib-row foodlib-tray-row" data-tray="${a.id}">
      <div class="foodlib-row-main"><span class="sg-name">${esc(a.name)}</span><span class="sg-meta">${esc(t('foodlib.trayBy', { name: a.contributorName || t('foodlib.anonUser') }))}</span>${flags ? `<span class="sg-meta">⚠️ ${esc(flags)}</span>` : ''}</div>
      ${foodlibValFieldsHTML('tray', a)}
      <div class="foodlib-row-btns">
        <button type="button" class="btn-primary btn-sm" data-fl-approve="${a.id}">${esc(t('libcom.approve'))}</button>
        <select data-tray-reason="${a.id}">${['valores', 'duplicado', 'no-unico', 'nombre'].map(r => `<option value="${r}">${esc(foodlibReasonText(r))}</option>`).join('')}</select>
        <button type="button" class="btn-ghost btn-sm" data-fl-reject="${a.id}">${esc(t('libcom.reject'))}</button>
      </div></div>`; }).join('') +
    reportes.map(r => `<div class="foodlib-row"><div class="foodlib-row-main"><span class="sg-name">${esc(t('foodlib.reportOf', { name: r.foodName }))}</span><span class="sg-meta">${esc(foodlibReasonText(r.reason))}</span></div><div class="foodlib-row-btns"><button type="button" class="btn-primary btn-sm" data-fl-resolve="${r.id}">${esc(t('foodlib.state.resuelto'))}</button></div></div>`).join('');
  sub.querySelectorAll('[data-tray]').forEach(row => {
    const unitSel = row.querySelector('[data-vf="qtyUnit"]');
    if (unitSel) unitSel.onchange = () => { const w = row.querySelector('[data-vf-piece]'); if (w) w.style.display = unitSel.value === 'unidad' ? '' : 'none'; };
  });
  sub.querySelectorAll('[data-fl-approve]').forEach(b => b.onclick = async () => {
    const row = sub.querySelector(`[data-tray="${b.dataset.flApprove}"]`); if (!row) return;
    const v = foodlibValsFrom(row);
    if (foodlibValidate(v).hard.length) { toast(t('foodlib.errHard'), true); return; }
    try {
      const ref = await addDoc(collection(db, 'food_library'), foodlibCleanFicha(v));
      await setDoc(doc(db, 'food_contrib', b.dataset.flApprove),
        { estado: 'aprobado', publicId: ref.id, resolvedBy: auth.currentUser.uid, resolvedAt: serverTimestamp() }, { merge: true });
      foodlibSugCache.clear();
      toast(t('foodlib.publishedToast'));
      foodlibLoadTray();
      if (foodlibIsOpen) foodlibLoadList(true);
    } catch { toast(t('foodlib.errHard'), true); }
  });
  sub.querySelectorAll('[data-fl-reject]').forEach(b => b.onclick = async () => {
    const sel = sub.querySelector(`[data-tray-reason="${b.dataset.flReject}"]`);
    try {
      await setDoc(doc(db, 'food_contrib', b.dataset.flReject),
        { estado: 'rechazado', rejectReason: sel ? sel.value : 'valores', resolvedBy: auth.currentUser.uid, resolvedAt: serverTimestamp() }, { merge: true });
      toast(t('foodlib.rejectedToast'));
      foodlibLoadTray();
    } catch { toast(t('foodlib.errHard'), true); }
  });
  sub.querySelectorAll('[data-fl-resolve]').forEach(b => b.onclick = async () => {
    try {
      await setDoc(doc(db, 'food_contrib', b.dataset.flResolve),
        { estado: 'resuelto', resolvedBy: auth.currentUser.uid, resolvedAt: serverTimestamp() }, { merge: true });
      toast(t('foodlib.resolvedToast'));
      foodlibLoadTray();
    } catch { toast(t('foodlib.errHard'), true); }
  });
}
$('m-photo').addEventListener('change', e => {
  const f = e.target.files[0];
  const prev = $('m-photo-preview');
  if (f) { prev.src = URL.createObjectURL(f); prev.style.display = 'block'; }
  else { prev.src = ''; prev.style.display = 'none'; }
});

let mealSaving = false; // guardia anti-duplicado del guardado de comidas (M8, 2026-10-17)
/* A-G2 (2026-10-31): identidad pendiente de la vía manual — el id de
   documento generado en el cliente para la comida que se está
   intentando guardar y la huella de sus datos; vive solo en memoria
   y se consume al primer guardado con éxito. */
let mealManualPending = null;
$('form-meal').addEventListener('submit', async e => {
  e.preventDefault();
  if (mealSaving) return; // ya hay un guardado en curso: el segundo envío se ignora
  const data = {
    ownerUid: auth.currentUser.uid,
    date: $('m-date').value, meal: $('m-meal').value,
    food: $('m-food').value.trim(), qty: $('m-qty').value.trim(),
    kcal: Math.max(0, num($('m-kcal').value)), prot: Math.max(0, num($('m-prot').value)),
    carb: Math.max(0, num($('m-carb').value)), sugar: Math.max(0, num($('m-sugar').value)),
    fat: Math.max(0, num($('m-fat').value)), notes: $('m-notes').value.trim(),
    createdAt: serverTimestamp()
  };
  /* FIBRA (Fase 1): campo opcional — vacío = el registro nace SIN
     el dato (nunca 0 forzado); con valor, se guarda a 1 decimal. */
  if ($('m-fiber').value.trim() !== '') data.fiber = Math.round(Math.max(0, num($('m-fiber').value)) * 10) / 10;
  if (!data.date || !data.food) { toast(t('err.mealMissing'), true); return; }
  mealSaving = true;
  const saveBtn = e.target.querySelector('button[type="submit"]');
  /* El guardado SE VE desde el primer instante (corrección del
     reporte «Guardar no hace nada», 2026-11-04): el botón dice
     «Guardando…» mientras la escritura viaja — antes el único cambio
     era el atributo disabled, invisible, y si la red tardaba el
     formulario parecía muerto —; si a los 8 s sigue en curso, el
     mismo botón avisa en lenguaje simple que sigue guardando y que
     se revise la conexión. Nunca más un guardado en silencio. */
  const saveBtnTxt = saveBtn ? saveBtn.textContent : '';
  let saveSlowTimer = null;
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.textContent = t('msg.saving');
    saveSlowTimer = setTimeout(() => { if (mealSaving && saveBtn) saveBtn.textContent = t('meal.savingSlow'); }, 8000);
  }
  try {
    const photoFile = $('m-photo').files[0];
    if (photoFile) {
      try {
        toast(t('msg.uploading'));
        const path = `nutrition/${auth.currentUser.uid}/meals/${Date.now()}.jpg`;
        const up = await uploadPhoto(photoFile, path);
        data.photoURL = up.url; data.photoPath = up.path;
      } catch (err) { toast(t('err.mealPhotoFail'), true); }
    }
    if (aiDraft) { data.source = aiDraft.src || 'ai'; data.ai = { model: aiDraft.model, rangeKcal: aiDraft.rangeKcal }; }
    /* Procedencia de la repetición (corrección 2026-10-19, punto 3b):
       si el guardado viene de «Repetir», la copia lleva su origin
       (kind/fromId/fromDate) — visible en los datos, sin bloque ai ni
       source:'ai': la estimación no se convierte en medición exacta
       ni se resucita su foto. repeatCtx se limpia tras la escritura;
       la ruta de IA es incompatible (aiClearDraft y repeatCtx nunca
       conviven: repetir limpia el borrador y viceversa). */
    if (repeatCtx) data.origin = { kind: repeatCtx.kind, fromId: repeatCtx.fromId, fromDate: repeatCtx.fromDate };
    /* Desglose por alimento (2026-10-21): el candidato viene del
       borrador de análisis o de la repetición, y SOLO se persiste si
       su suma sigue igualando los totales FINALES del formulario —
       cualquier edición que descuadre lo descarta en silencio y el
       registro queda en el modo por registro de siempre. */
    const candItems = (aiDraft && aiDraft.items) || (repeatCtx && repeatCtx.items) || (mealEditCtx && !aiDraft && mealEditCtx.rec && mealEditCtx.rec.items) || null;
    const formIts = itemsIfSquare(candItems, data);
    if (formIts) data.items = formIts;
    /* Edición de un registro guardado (AUTH-2026-11-06-291): el
       guardado actualiza ESE registro — el documento se reescribe
       entero, así que se conserva lo que el formulario no edita: su
       hora de registro original, su foto si no se eligió otra, su
       procedencia (source/origin/ai) y su autoría (byUid/byRole). El
       desglose viaja como candidato por candItems y solo persiste si
       sigue cuadrando, la regla de honestidad de siempre. Con un
       borrador de IA vivo manda la vía de IA (guarda !aiDraft): los
       dos episodios nunca conviven. Si se eligió foto nueva, la
       anterior se retira de Storage tras escribir (abajo). */
    let editReplacedPhoto = null;
    if (mealEditCtx && !aiDraft) {
      const rec = mealEditCtx.rec || {};
      if (rec.createdAtMs) data.createdAt = Timestamp.fromMillis(rec.createdAtMs);
      if (!photoFile) {
        if (rec.photoURL) data.photoURL = rec.photoURL;
        if (rec.photoPath) data.photoPath = rec.photoPath;
      } else if (rec.photoPath && rec.photoPath !== data.photoPath) {
        editReplacedPhoto = rec.photoPath;
      }
      if (rec.source) data.source = rec.source;
      if (rec.origin) data.origin = rec.origin;
      if (rec.ai) data.ai = rec.ai;
      if (rec.byUid) data.byUid = rec.byUid;
      if (rec.byRole) data.byRole = rec.byRole;
    }
    const wasDraft = !!aiDraft;
    /* ¿Lo repartiste? en el formulario manual: con el reparto
       encendido el registro completo de arriba NO se escribe — se
       escriben DOS asientos normales e independientes, uno por
       momento, cada uno con la mitad de los totales del formulario
       (aiSplitHalves: resto exacto, las dos mitades suman el original
       al número), de la cantidad (texto libre partido con
       mealSplitQtyHalves) y del desglose (aiItemsHalved, revalidado
       contra los totales de CADA mitad con itemsIfSquare, la misma
       regla de honestidad de la hoja). El rango de la estimación, si
       lo hay, se parte como en la hoja (la misma mitad para ambos).
       La candidatura a la biblioteca sigue UNA vez con el registro
       completo (el foodlibAutoCandidate de abajo no cambia). */
    const splitOn = !!mealSplit;
    const splitSecond = splitOn ? mealSplitSecond() : null;
    let dataA = null, dataB = null, idA = null;
    if (splitOn) {
      const hv = aiSplitHalves(data);
      const itH = aiItemsHalved(data.items);
      const qh = mealSplitQtyHalves();
      const rangeHalf = (data.ai && Array.isArray(data.ai.rangeKcal)) ? [Math.round(data.ai.rangeKcal[0] / 2), Math.round(data.ai.rangeKcal[1] / 2)] : null;
      const mkHalf = (meal, h, its, qty) => {
        const d = Object.assign({}, data, { meal, qty }, h);
        if (data.ai) d.ai = { model: data.ai.model, rangeKcal: rangeHalf };
        delete d.items;
        const hi = itemsIfSquare(its, d);
        if (hi) d.items = hi;
        return d;
      };
      dataA = mkHalf(data.meal, hv[0], itH[0], qh.qa);
      dataB = mkHalf(splitSecond, hv[1], itH[1], qh.qb);
      /* La foto queda SOLO en la primera mitad: hay un único objeto
         en Storage y el borrado de un registro elimina el objeto de
         su photoPath — compartirlo dejaría a la otra mitad sin foto
         el día que se borre esta. */
      delete dataB.photoURL; delete dataB.photoPath;
    }
    /* Identidad de guardado del borrador de IA (corrección del
       duplicado, 2026-10-23): si el formulario viene de una revisión
       de análisis, escribe el MISMO documento que el guardado directo
       de esa revisión — nunca un segundo registro del mismo plato. */
    /* A-G1 + A-G2 (revisión «una sola sección visible», 2026-10-31):
       la escritura va envuelta: si FALLA, se avisa con su causa
       (failToast, el patrón honesto de la casa) y el formulario
       queda abierto con todo lo escrito para reintentar — antes el
       try/finally sin catch dejaba el fallo en silencio. Y la vía
       manual deja de usar addDoc (no idempotente: un reintento tras
       una respuesta perdida DUPLICABA la comida): la ficha nace con
       un id generado en el cliente, del mismo formato «meal_…» del
       saveId de la vía IA, y ese id se REUTILIZA mientras la huella
       de los datos sea la misma — reintentar la misma comida
       reescribe el mismo documento en vez de crear otro; teclear
       otra cosa genera un id nuevo. El documento guardado no cambia:
       mismas claves y valores que con addDoc; solo cambia quién
       genera el id, como ya hacía la vía IA desde 2026-10-23. */
    try {
      if (aiDraft && aiDraft.saveId) idA = aiDraft.saveId;
      else if (mealEditCtx && !aiDraft) idA = mealEditCtx.id; // AUTH-291: editar escribe sobre el MISMO documento, sin huella ni id nuevo
      else {
        /* Con reparto, la huella se extiende con la segunda comida:
           repartir el mismo plato a otro momento es OTRO guardado a
           efectos de reintento. Sin reparto, la huella queda
           carácter a carácter como siempre. */
        /* La fibra entra en la huella SOLO cuando el registro la
           trae: sin fibra, la huella queda carácter a carácter
           como siempre (ningún reintento viejo cambia de id). */
        const huella = [data.ownerUid, data.date, data.meal, data.food, data.qty, data.kcal, data.prot, data.carb, data.sugar, data.fat].join('|') + (data.fiber != null ? '|fib:' + data.fiber : '') + (splitOn ? '|mitad:' + splitSecond : '');
        if (!mealManualPending || mealManualPending.huella !== huella) mealManualPending = { huella, id: aiNewSaveId() };
        idA = mealManualPending.id;
      }
      if (splitOn) {
        /* El par nace JUNTO o no nace: un solo lote atómico con los
           dos documentos y los ids estables de arriba (el del
           guardado y su par «-b») — un reintento tras un fallo
           reescribe LOS MISMOS dos documentos, jamás duplica. */
        const batch = writeBatch(db);
        batch.set(doc(db, 'nutrition_meals', idA), dataA);
        batch.set(doc(db, 'nutrition_meals', idA + '-b'), dataB);
        await batch.commit();
      } else {
        await setDoc(doc(db, 'nutrition_meals', idA), data);
      }
      if (!(aiDraft && aiDraft.saveId)) mealManualPending = null;
    } catch (err) { failToast(err); return; }
    /* AUTH-291: la escritura ya aterrizó — si la edición trajo foto
       nueva, la foto anterior del registro se retira de Storage. */
    if (editReplacedPhoto) { try { await deleteObject(sRef(storage, editReplacedPhoto)); } catch {} }
    /* Punto 84: si este guardado es el de una elección del
       catálogo, su aterrizaje es el de la revisión de IA (caer en
       Consumido), no la vuelta al origen. Se lee ANTES de que los
       resets de abajo limpien la elección. */
    const wasPick = !!MEAL_PICK;
    aiClearDraft();
    repeatClear();
    mealSplit = null;
    /* El registro YA se guardó: el espejo de borrador (D3) se
       limpia — lo escrito no debe seguir figurando como sin guardar
       ni escribirse dos veces. */
    try { pendDraftClear(); pendDraftDisarm(); } catch {}
    $('meal-modal').style.display = 'none';
    if (wasPick) {
      backClear();
      /* Diferido como la vuelta de backReturn: reabrir la ventana
         dentro del mismo gesto dejaría el clic a merced de los
         vigilantes de clic fuera de la familia Comida. */
      setTimeout(() => { try { foodOpenFloat(); foodSetSub('consumido'); } catch {} }, 0);
    } else backReturn(true);
    e.target.reset();
    $('m-photo-preview').style.display = 'none'; $('m-photo-preview').src = '';
    await loadAllKeepDate(data.date);
    if (splitOn) {
      /* La confirmación del reparto es la de la familia (la misma
         de la hoja de la IA), con la línea breve de la foto o de la
         voz cuando el registro viene de un análisis. */
      toast(t('ai.savedSplit', { a: mealName(dataA.meal), b: mealName(dataB.meal) }) + (data.source === 'ai' ? ' ' + t('ai.savedPhotoNote') : data.source === 'ai-audio' ? ' ' + t('aiVoice.savedNote') : ''));
    } else if (wasDraft) {
      /* Confirmación visible del borrador (H-2): las kcal guardadas y el
         total del día YA incluyéndolas — que «sí suma» sea evidente. */
      const dayTotal = (MEALS[data.date] || []).reduce((s, m) => s + (Number(m.kcal) || 0), 0);
      /* La línea breve de la foto (ai.savedPhotoNote) va SOLO si
         el borrador vino de una FOTO (source 'ai'); el borrador de
         texto ('ai-text') confirma sin ella, como el guardado
         directo; el de VOZ ('ai-audio') lleva su línea gemela
         (aiVoice.savedNote: la nota de voz no se guardó). */
      toast(t('ai.savedInfo', { kcal: Math.round(data.kcal), total: Math.round(dayTotal) }) + (data.source === 'ai' ? ' ' + t('ai.savedPhotoNote') : data.source === 'ai-audio' ? ' ' + t('aiVoice.savedNote') : ''));
    } else {
      toast(t('msg.mealSaved'));
    }
    /* Candidato automático a la antesala (corrección de P1,
       2026-10-31): sin oferta ni pregunta — el alimento guardado
       pasa solo a la bandeja de aprobación de Administración. En
       segundo plano y en silencio; jamás bloquea este guardado. */
    try { foodlibAutoCandidate(data); } catch {}
  } finally {
    mealSaving = false;
    if (saveSlowTimer) clearTimeout(saveSlowTimer);
    if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = saveBtnTxt; }
  }
});

/* weightCtx: null = pesaje propio nuevo; {uid, docId, rec} = editar (propio o de un cliente, solo dueño) */
let weightCtx = null;
function openWeightModal(ctx) {
  weightCtx = ctx || null;
  const rec = ctx && ctx.rec;
  $('w-date').value = (rec && rec.date) || todayISO();
  /* MÓDULO H: el peso se muestra y se teclea en la unidad del VISOR;
     lo guardado sigue siendo kg canónico (ver el submit). Si el
     registro trae su valor original en esta misma unidad, se
     muestra ese (exacto, sin reconversión). */
  const wl = $('w-weight-label'); if (wl) wl.textContent = t('units.weightField', { u: UNIT_PREFS.mass });
  $('w-weight').value = rec ? weightDisplayOf(rec) : '';
  $('w-fat').value = (rec && rec.fat) || '';
  $('w-muscle').value = (rec && rec.muscle) || '';
  $('w-water').value = (rec && rec.water) || '';
  $('w-visceral').value = (rec && rec.visceral) || '';
  $('w-notes').value = (rec && rec.notes) || '';
  /* Formulario POR ROL (correo 2026-10-23 18:23, que REDEFINE el
     de 17:48 en lo solapado): el PESO lo ingresa SIEMPRE el
     usuario; los PORCENTAJES (grasa, músculo, agua, visceral) y
     las NOTAS quedan deshabilitados para el usuario SIN permiso
     expreso de su entrenador (el interruptor compAccess), con la
     nota visible. En la vista del entrenador (contexto de cliente)
     todo queda habilitado. */
  const pctLocked = (!ctx || ctx.uid === auth.currentUser.uid) && !compClientCanEdit();
  ['w-fat', 'w-muscle', 'w-water', 'w-visceral', 'w-notes'].forEach(idF => { const el = $(idF); if (el) el.disabled = pctLocked; });
  const pn = $('w-pct-note'); if (pn) { pn.style.display = pctLocked ? '' : 'none'; pn.textContent = t('compacc.pctNote'); }
  /* AUTH-153 (punto 13, parte 2): con el candado puesto, junto a la
     nota va su línea POSITIVA — el peso lo guarda siempre la propia
     alumna; el candado es solo de la composición. */
  const pp = $('w-pct-pos'); if (pp) { pp.style.display = pctLocked ? '' : 'none'; pp.textContent = t('compacc.yourWeight'); }
  $('weight-modal').style.display = '';
}
$('btn-add-weight').onclick = () => openWeightModal(null);
$('weight-cancel').onclick = () => { $('weight-modal').style.display = 'none'; weightCtx = null; backReturn(); };
$('weight-modal').addEventListener('click', e => { if (e.target.id === 'weight-modal') { e.target.style.display = 'none'; weightCtx = null; backReturn(); } });

$('form-weight').addEventListener('submit', async e => {
  e.preventDefault();
  const date = $('w-date').value;
  const uid = (weightCtx && weightCtx.uid) || auth.currentUser.uid;
  const docId = (weightCtx && weightCtx.docId) || `${uid}_${date}`;
  /* Con los porcentajes bloqueados, el guardado del usuario escribe
     su PESO y CONSERVA los porcentajes/notas ya registrados por el
     entrenador (del registro que se edita): nunca los pisa a cero. */
  const pctLocked = uid === auth.currentUser.uid && !compClientCanEdit();
  const prevRec = (weightCtx && weightCtx.rec) || {};
  /* MÓDULO H: la entrada llega en la unidad del visor y se guarda
     en kg CANÓNICO, con el patrón {valueCanonical, valueOriginal,
     unitOriginal}. Rango canónico H-5: 20–400 kg. */
  const wDisp = num($('w-weight').value);
  const wCanon = massToCanonical(wDisp);
  if (date && wDisp > 0 && !(wCanon >= 20 && wCanon <= 400)) { toast(t('units.errWeightRange'), true); return; }
  const data = { ownerUid: uid, date, weight: wCanon, weightOriginal: wDisp, weightUnitOriginal: UNIT_PREFS.mass,
    fat: pctLocked ? Math.max(0, num(prevRec.fat)) : Math.max(0, num($('w-fat').value)),
    muscle: pctLocked ? Math.max(0, num(prevRec.muscle)) : Math.max(0, num($('w-muscle').value)),
    water: pctLocked ? Math.max(0, num(prevRec.water)) : Math.max(0, num($('w-water').value)),
    visceral: pctLocked ? Math.max(0, num(prevRec.visceral)) : Math.max(0, num($('w-visceral').value)),
    notes: pctLocked ? String(prevRec.notes || '') : $('w-notes').value.trim(),
    updatedAt: serverTimestamp() };
  if (!date || data.weight <= 0) { toast(t('err.weightMissing'), true); return; }
  /* Aviso HONESTO (corrección «Registrar pesaje», 2026-10-23): si el
     guardado es rechazado (p. ej. las reglas vivas aún no admiten que
     el entrenador cree el primer pesaje de un cliente), el error se
     MUESTRA con su causa (patrón errCauseKey/failToast de 2026-10-20)
     y el modal queda ABIERTO con los datos intactos: nunca más un
     fallo en silencio que parece un guardado. */
  try {
    await setDoc(doc(db, 'nutrition_weight', docId), data);
  } catch (err) {
    /* AUTH-153 (punto 13, parte 2): un guardado de SOLO-PESO propio
       (pctLocked: la carga conserva la composición, no la cambia)
       jamás despacha el texto genérico de permiso — ese texto fue
       el síntoma visible del defecto de reglas. Si aun así rebota
       por permiso, el aviso nombra el peso y pide reintentar, sin
       culpar a la cuenta ni mandar a avisar al entrenador. */
    if (pctLocked && ((err && err.code) || '').includes('permission-denied')) {
      try { console.warn('[ronbo] guardado de solo-peso denegado:', err.code); } catch {}
      toast(t('err.weightSaveDenied'), true);
    } else failToast(err);
    return;
  }
  $('weight-modal').style.display = 'none';
  backReturn(true);
  e.target.reset();
  const wasClient = weightCtx && weightCtx.uid !== auth.currentUser.uid;
  const clientUid = weightCtx && weightCtx.uid;
  weightCtx = null;
  toast(t('msg.weightSaved'));
  if (wasClient) await openClient(clientUid); else {
    try { await loadAll(); }
    catch (loadErr) {
      /* AUTH-153 (punto 13, parte 3): el guardado YA ocurrió; si la
         recarga falla (p. ej. lecturas en 429), el registro se
         fusiona en memoria y se repinta el pesaje — un guardado
         bueno nunca debe parecer no guardado (WEIGHTS viejo). */
      try { console.warn('[ronbo] recarga tras guardar el peso falló; fusión en memoria:', (loadErr && loadErr.code) || String(loadErr)); } catch {}
      const recW = { id: docId, date, weight: data.weight,
        fat: data.fat, muscle: data.muscle, water: data.water, visceral: data.visceral, notes: data.notes,
        weightOriginal: data.weightOriginal, weightUnitOriginal: data.weightUnitOriginal };
      const ixW = WEIGHTS.findIndex(w => w.id === docId);
      if (ixW >= 0) WEIGHTS[ixW] = recW; else { WEIGHTS.push(recW); WEIGHTS.sort((a, b) => a.date < b.date ? -1 : 1); }
      try { renderWeight(); } catch {}
      try { Promise.resolve(refreshDynamic()).catch(() => {}); } catch {}
    }
    try { await evalReconcile(date); } catch {}
  }
});

/* Mostrar/ocultar la contraseña (ojito discreto junto al campo) */
