    const im = new Image();
    im.onload = () => { r.img = im; r.state = 'ok'; const f = $('share-float'); if (f && f.style.display !== 'none' && SHARE.type === 'trans') shareRender(); };
    im.onerror = () => { r.state = 'fail'; };
