  sgText(ctx, LANG === 'es' ? 'Come bien. Entrena fuerte. Vive el presente.' : 'Eat well. Train strong. Live present.', W / 2, eslCy, 800, M.esl, '#0b5563', { align: 'center' });
  /* El pie oscuro de la familia */
  sgBox(ctx, 0, pieTop, W, M.pie, 0, '#062a33');
