/* ============================================================
   CRONÓMETRO DEPORTIVO LIBRE (2026-10-27, diseño
   DISEÑO-CRONOMETRO-DEPORTIVO-2026-10-27, previa aprobada por
   Ronald tal cual). Herramienta a pantalla completa sobre el
   papel tapiz de la marca. Es LIBRE: no escribe Firestore, ni
   toca el cronómetro de la sesión del plan (trainChrono*), ni
   la llamita, ni el motor de metas — no guarda ningún registro.
   PERSISTENCIA EN EL DISPOSITIVO (corrección 2026-11-04, reporte
   en vivo de Ronald: «activé el cronómetro, me salí de la app y
   se perdió»): el estado en curso (instante de arranque del
   tramo, acumulado y vueltas) se sella en localStorage en cada
   cambio y se restaura al abrir la app, con el reloj de pared
   (Date.now()): salir y volver ya no lo pierde y el tiempo que
   pasa fuera SIGUE contando, porque el transcurrido se CALCULA
   desde las marcas guardadas en cada pintado, jamás se cuenta
   por ticks. Un sello de un día anterior se descarta al
   restaurar: el cronómetro de ayer no resucita hoy. Al ponerlo
   a cero, el sello se borra.
   ============================================================ */
const STOPW = { open: false, running: false, startAt: 0, acc: 0, laps: [], raf: 0 };
const SW_LS_KEY = 'ronbofit-stopwatch-v1';
function swSave() {
  try {
    if (!STOPW.running && STOPW.acc <= 0 && !STOPW.laps.length) { localStorage.removeItem(SW_LS_KEY); return; }
    localStorage.setItem(SW_LS_KEY, JSON.stringify({
      running: STOPW.running, startAt: STOPW.startAt, acc: STOPW.acc,
      laps: STOPW.laps, day: todayISO() }));
  } catch {}
}
function swRestore() {
  try {
    const raw = localStorage.getItem(SW_LS_KEY);
    if (!raw) return;
    const v = JSON.parse(raw);
    if (!v || v.day !== todayISO() || typeof v.acc !== 'number') { localStorage.removeItem(SW_LS_KEY); return; }
    STOPW.acc = v.acc;
    STOPW.laps = Array.isArray(v.laps) ? v.laps.filter(l => l && typeof l.lapMs === 'number' && typeof l.totalMs === 'number') : [];
    if (v.running && typeof v.startAt === 'number') { STOPW.running = true; STOPW.startAt = v.startAt; }
    else { STOPW.running = false; STOPW.startAt = 0; }
  } catch {}
}
function swElapsed() { return STOPW.acc + (STOPW.running ? Date.now() - STOPW.startAt : 0); }
function swPad2(n) { return String(n).padStart(2, '0'); }
function swFmtParts(ms) {
  const cs = Math.floor(ms / 10) % 100, s = Math.floor(ms / 1000) % 60, m = Math.floor(ms / 60000);
  return { main: swPad2(m) + ':' + swPad2(s), cs: '.' + swPad2(cs), full: swPad2(m) + ':' + swPad2(s) + '.' + swPad2(cs) };
}
function swLapBase() { return STOPW.laps.reduce((a, l) => a + l.lapMs, 0); }
function swSetBtn(el, label, cls, disabled) {
  if (!el) return;
  el.textContent = label;
  el.className = 'sw-cbtn ' + cls;
  if (disabled) el.setAttribute('disabled', ''); else el.removeAttribute('disabled');
}
function swPaint() {
  const ov = $('sw-overlay'); if (!ov) return;
  const el = swElapsed(), f = swFmtParts(el);
  const main = $('sw-time-main'), csEl = $('sw-time-cs');
  if (main) main.textContent = f.main;
  if (csEl) csEl.textContent = f.cs;
  const st = $('sw-status');
  if (st) {
    if (STOPW.running) { st.textContent = t('sw.running'); st.className = 'sw-status run'; }
    else if (el > 0) { st.textContent = t('sw.paused'); st.className = 'sw-status pause'; }
    else { st.textContent = ''; st.className = 'sw-status'; }
  }
  const sub = $('sw-sub');
  if (sub) {
    if (STOPW.running) sub.innerHTML = esc(t('sw.currentLap')) + ' · <b>' + swFmtParts(el - swLapBase()).full + '</b>';
    else if (STOPW.laps.length) sub.textContent = t(STOPW.laps.length === 1 ? 'sw.totalLaps1' : 'sw.totalLaps', { n: STOPW.laps.length });
    else sub.textContent = '';
  }
  const ring = $('sw-ring');
  if (ring) ring.classList.toggle('sm', STOPW.laps.length > 0);
  const lapsEl = $('sw-laps');
  if (lapsEl) {
    lapsEl.innerHTML = STOPW.laps.map((l, i) =>
      '<div class="lr"><span class="ln">' + esc(t('sw.lapN', { n: i + 1 })) + '</span>' +
      '<span class="lt">' + swFmtParts(l.lapMs).full + '</span>' +
      '<span class="lp">' + esc(t('sw.split')) + '</span></div>').reverse().join('');
  }
  const L = $('sw-btn-left'), M = $('sw-btn-main'), R = $('sw-btn-right');
  if (STOPW.running) {
    swSetBtn(L, t('sw.lap'), 'side', false);
    swSetBtn(M, t('sw.pause'), 'main amber', false);
    swSetBtn(R, t('sw.reset'), 'side', false);
  } else if (el > 0) {
    swSetBtn(L, t('sw.reset'), 'side', false);
    swSetBtn(M, t('sw.resume'), 'main green', false);
    swSetBtn(R, t('sw.lap'), 'side', false);
  } else {
    swSetBtn(L, t('sw.reset'), 'side', true);
    swSetBtn(M, t('sw.start'), 'main green', false);
    swSetBtn(R, t('sw.lap'), 'side', true);
  }
}
function swTick() {
  if (!STOPW.open) { STOPW.raf = 0; return; }
  swPaint();
  STOPW.raf = STOPW.running ? requestAnimationFrame(swTick) : 0;
}
function swKick() { if (STOPW.open && STOPW.running && !STOPW.raf) STOPW.raf = requestAnimationFrame(swTick); }
function swMainAction() {
  if (STOPW.running) { STOPW.acc += Date.now() - STOPW.startAt; STOPW.running = false; }
  else { STOPW.startAt = Date.now(); STOPW.running = true; swKick(); }
  swSave();
  swPaint();
}
function swLapAction() {
  const el = swElapsed(); if (el <= 0) return;
  const prev = swLapBase();
  STOPW.laps.push({ lapMs: el - prev, totalMs: el });
  swSave();
  swPaint();
}
function swResetAction() {
  STOPW.running = false; STOPW.acc = 0; STOPW.startAt = 0; STOPW.laps = [];
  swSave();
  swPaint();
}
function swSideAction(side) {
  if (STOPW.running) { if (side === 'left') swLapAction(); else swResetAction(); }
  else if (swElapsed() > 0) { if (side === 'left') swResetAction(); else swLapAction(); }
}
function swOpenTool() {
  const ov = $('sw-overlay'); if (!ov) return;
  STOPW.open = true;
  ov.style.display = 'block';
  swPaint(); swKick();
}
function swCloseTool() {
  const ov = $('sw-overlay'); if (!ov) return;
  STOPW.open = false;
  if (STOPW.raf) { cancelAnimationFrame(STOPW.raf); STOPW.raf = 0; }
  ov.style.display = 'none';
}
function swRelang() { if (STOPW.open) swPaint(); }
/* Botón redondo flotante (sustituye a la pastilla): refleja el estado
   del cronómetro cuando la herramienta está minimizada — anillo
   pulsante y tiempo vivo si corre; tiempo congelado con ❚❚ si está
   en pausa; nada si está a cero. Solo pinta DOM: no escribe nada. */
let SW_FAB_LAST = '';
function swFabPaint() {
  const fab = $('btn-stopwatch'); if (!fab) return;
  const el = swElapsed();
  let cls = 'sw-fab', txt = '';
  if (STOPW.running) { cls = 'sw-fab live'; txt = swFmtParts(el).main; }
  else if (el > 0) { cls = 'sw-fab paused'; txt = '❚❚ ' + swFmtParts(el).main; }
  if (fab.className !== cls) fab.className = cls;
  const lab = $('sw-fab-time');
  if (lab && SW_FAB_LAST !== txt) { lab.textContent = txt; SW_FAB_LAST = txt; }
}
(function swInit() {
  swRestore();
  const fab = $('btn-stopwatch'); if (fab) fab.addEventListener('click', swOpenTool);
  swFabPaint();
  setInterval(() => { if (!STOPW.open) swFabPaint(); }, 250);
  const x = $('sw-close'); if (x) x.addEventListener('click', swCloseTool);
  const M = $('sw-btn-main'); if (M) M.addEventListener('click', swMainAction);
  const L = $('sw-btn-left'); if (L) L.addEventListener('click', () => swSideAction('left'));
  const R = $('sw-btn-right'); if (R) R.addEventListener('click', () => swSideAction('right'));
})();

(function installCardInit() {
  try {
    /* La marca histórica «ya visto» deja de suprimir: se retira. */
    try { localStorage.removeItem('ronbofit-install-card-seen'); } catch (e) {}
    const ov = document.getElementById('install-card-overlay');
    if (!ov) return;
    const close = () => { installCardDismissed = true; ov.style.display = 'none'; };
    const x = document.getElementById('install-card-close');
    if (x) x.addEventListener('click', close);
    const ok = document.getElementById('install-card-ok');
    if (ok) ok.addEventListener('click', close);
    window.addEventListener('appinstalled', close);
    setTimeout(installCardMaybeShow, 650);
  } catch (e) { /* el mensaje de instalación nunca rompe el acceso */ }
})();

