const MM_DAY_TYPES = ['base', 'exigente', 'descanso'];
const MM_TOL = 0.10;
const MM_DEFAULT_TIMES = { Desayuno: '07:00', Almuerzo: '12:30', Merienda: '16:00', Cena: '19:30', Snack: '21:00' };
let MENU = null;
