/* Tarjeta del menú en la consola del coach (la rellena
   mealPlanConsoleFill junto al estado del plan). */
/* ═══ PLANIFICADOR SEMANAL EN COMIDA — variante C (decisiones de
   Ronald, chat RONBO.NUTRI: 2026-11-08 23:39 «en el área de comida
   quiero ver mi planificador de comidas semanal»; 2026-11-09 00:03
   plan y diario SEPARADOS y «Mi plan alimenticio» con el coach
   como «Su plan para ti»; 2026-11-09 00:15 variante C aprobada).
   La RAÍZ del planificador es esta hoja (#plan-float): la abren la
   tarjeta de la ventana de Comida y el botón grande de «Mi coach
   de alimentación». Pinta la semana CONSTRUIDA de verdad desde los
   documentos nutrition_menus de siempre (AUTH-296/297) — hoy
   desplegado, los demás días plegados, flechas de semana como las
   del editor — y su única puerta al editor es planOpenEditor, que
   cierra la hoja (y la ventana de Comida si estaba abierta) antes
   de abrir #nutri-float: una sola vía, sin hojas apiladas. El
   diario «Hoy» no se toca: menú y diario no se leen entre sí. ═══ */
const PLANWK = { weekStart: null, showing: 'own', openDay: null, sc: null, editorWeek: null };

function planWeekRange(weekStart) {
  const a = String(weekStart || ''), b = planISOAddDays(a, 6);
  const pa = a.split('-'), pb = String(b).split('-');
  if (pa.length < 3 || pb.length < 3) return a;
  const d1 = parseInt(pa[2], 10), d2 = parseInt(pb[2], 10);
  const m1 = parseInt(pa[1], 10) - 1, m2 = parseInt(pb[1], 10) - 1;
  if (LANG === 'es') return m1 === m2 ? `${d1} al ${d2} de ${MESES_ES[m1]}` : `${d1} de ${MESES_ES[m1]} al ${d2} de ${MESES_ES[m2]}`;
  return m1 === m2 ? `${MESES_EN[m1]} ${d1} – ${d2}` : `${MESES_EN[m1]} ${d1} – ${MESES_EN[m2]} ${d2}`;
}
/* La banda del día con la MISMA regla del editor (mmMetricState,
   ±10 % en kcal): pastilla corta junto al total del día. */
function planBandChip(kcal, targetKcal, hasItems) {
  if (!hasItems || targetKcal == null) return '';
  const st = mmMetricState(kcal, targetKcal, 'kcal');
  if (st.state === 'ok') return `<span class="plan-chip ok">${esc(t('menu.onTarget'))}</span>`;
  if (st.state === 'over') return `<span class="plan-chip high">${esc(t('menu.over', { n: Math.round(st.diff) }))}</span>`;
  if (st.state === 'under') return `<span class="plan-chip low">${esc(t('menu.under', { n: Math.round(-st.diff) }))}</span>`;
  return '';
}
/* Qué menús hay en una semana, espejo del editor: el propio del
   alumno (mmMenuForWeek) y el vigente de su coach, si lo hay. */
function planResolveMenu(menus, weekStart, me) {
  const own = mmMenuForWeek(menus, weekStart, 'alumno', me);
  const coachVig = (menus || []).filter(m => m.weekStart === weekStart && m.authorRole === 'coach' && m.status === 'vigente')
    .sort((a, b) => String((b.updatedAt && b.updatedAt.seconds) || '').localeCompare(String((a.updatedAt && a.updatedAt.seconds) || '')))[0] || null;
  return { own, coachVig };
}
function planDayMealsHTML(day) {
  const meals = (day.meals || []).filter(m => (m.items || []).length);
  if (!meals.length) return `<p class="progress-hint">${esc(t('planwk.dayEmpty'))}</p>`;
  return meals.map(meal => {
    const mt = mmMealTotals(meal);
    const items = (meal.items || []).map(it => `<div class="plan-item"><span>${esc(it.name || '')}</span><span class="plan-item-g">${Math.round(Number(it.grams) || 0)} g</span></div>`).join('');
    return `<div class="plan-meal"><div class="plan-meal-top"><span class="plan-meal-time">${esc(meal.time || '')}</span><span class="plan-meal-name">${esc(mealName(meal.name))}</span><span class="plan-meal-kcal">${Math.round(mt.kcal)} kcal</span></div>${items}<div class="plan-meal-mac">${esc(t('th.protShort'))} ${acNum(mt.prot)} · ${esc(t('th.carbShort'))} ${acNum(mt.carb)} · ${esc(t('th.fatShort'))} ${acNum(mt.fat)} g</div></div>`;
  }).join('');
}
function planSheetHTML() {
  const me = auth.currentUser && auth.currentUser.uid;
  const wk = PLANWK.weekStart || mmMondayOf(todayISO());
  const menus = NUTRI.myMenus || [];
  const { own, coachVig } = planResolveMenu(menus, wk, me);
  if (PLANWK.showing === 'coach' && !coachVig) PLANWK.showing = 'own';
  if (PLANWK.showing === 'own' && !own && coachVig) PLANWK.showing = 'coach';
  const menu = PLANWK.showing === 'coach' ? coachVig : own;
  const sc = PLANWK.sc || {};
  const structure = sc.structure || null;
  const baseGoals = structure && structure.days && structure.days.base ? structure.days.base.goals : null;
  let h = `<div class="plan-wk-head"><button type="button" class="plan-wk-nav" id="plan-wk-prev" aria-label="‹">‹</button><div class="plan-wk-title">${esc(t('planwk.weekOf', { range: planWeekRange(wk) }))}</div><button type="button" class="plan-wk-nav" id="plan-wk-next" aria-label="›">›</button></div>`;
  if (baseGoals && baseGoals.kcal) h += `<p class="plan-sub">${esc(t('planwk.sub', { kcal: Math.round(baseGoals.kcal) }))}</p>`;
  if (menu) h += `<p class="progress-hint">${esc(t('menu.status.' + (menu.status || 'vigente')))} · ${esc(menu.authorRole === 'coach' ? t('menu.byCoach') : t('menu.byYou'))}${structure ? ' · ' + esc(t(sc.source === 'plan' ? 'menu.targetFromPlan' : 'menu.targetFromGoals')) : ''}</p>`;
  const prop = NUTRI.myMenuProposed;
  if (prop && prop.weekStart === wk) {
    h += `<div class="nutri-card mp-proposal"><b>🍽️ ${esc(t('menu.proposalTitle'))}</b><p class="progress-hint">${esc(t('planwk.proposalSub'))}</p><div class="eval-actions"><button type="button" class="btn-primary btn-sm" id="plan-open-proposal">${esc(t('menu.view'))}</button></div></div>`;
  }
  if (own && coachVig) {
    h += `<div class="plan-src"><button type="button" class="btn-ghost btn-sm" data-plan-src="own">${esc(t('menu.byYou'))}</button><button type="button" class="btn-ghost btn-sm" data-plan-src="coach">${esc(t('menu.byCoach'))}</button></div>`;
  }
  if (menu) {
    if (!structure) h += `<div class="nutri-card"><p class="progress-hint">${esc(t('menu.noGoals'))}</p></div>`;
    const byDate = {};
    (menu.days || []).forEach(d => { byDate[d.date] = d; });
    for (let i = 0; i < 7; i++) {
      const iso = planISOAddDays(wk, i);
      const day = byDate[iso] || { date: iso, dayType: 'base', meals: [] };
      const tot = mmDayTotals(day);
      const has = (day.meals || []).some(m => (m.items || []).length);
      const tgt = structure ? mmDayTarget(structure, day.dayType) : null;
      const isToday = iso === todayISO();
      const open = PLANWK.openDay === iso;
      const kcalTxt = tgt ? `${Math.round(tot.kcal)} / ${Math.round(tgt.kcal)} kcal` : `${Math.round(tot.kcal)} kcal`;
      h += `<div class="plan-day${isToday ? ' today' : ''}"><button type="button" class="plan-day-head" data-plan-day="${iso}" aria-expanded="${open}"><span class="plan-day-name">${esc(weekdayName(iso))} ${parseInt(iso.slice(8), 10)}</span>${isToday ? `<span class="plan-today-tag">${esc(t('planwk.today'))}</span>` : ''}<span class="plan-day-kcal">${esc(kcalTxt)}</span>${planBandChip(tot.kcal, tgt ? tgt.kcal : null, has)}<span class="plan-chev">${open ? '▴' : '▾'}</span></button>${open ? `<div class="plan-day-body">${planDayMealsHTML(day)}</div>` : ''}</div>`;
    }
  } else {
    h += `<div class="plan-empty"><p>${esc(t('menu.empty'))}</p></div>`;
  }
  h += `<button type="button" class="btn-primary plan-edit-btn" id="plan-open-editor">✏️ ${esc(t('planwk.editBtn'))}</button>`;
  return h;
}
function planPaintSheet() {
  const body = $('plan-sheet-body'); if (!body) return;
  body.innerHTML = planSheetHTML();
  const on = (id, fn) => { const el = $(id); if (el) el.onclick = fn; };
  const nav = delta => {
    PLANWK.weekStart = planISOAddDays(PLANWK.weekStart, delta);
    PLANWK.showing = 'own';
    const hoy = todayISO(), fin = planISOAddDays(PLANWK.weekStart, 6);
    PLANWK.openDay = (hoy >= PLANWK.weekStart && hoy <= fin) ? hoy : null;
    planPaintSheet();
  };
  on('plan-wk-prev', () => nav(-7));
  on('plan-wk-next', () => nav(7));
  on('plan-open-editor', () => planOpenEditor());
  on('plan-open-proposal', () => planOpenEditor());
  body.querySelectorAll('[data-plan-day]').forEach(b => { b.onclick = () => { const d = b.getAttribute('data-plan-day'); PLANWK.openDay = PLANWK.openDay === d ? null : d; planPaintSheet(); }; });
  body.querySelectorAll('[data-plan-src]').forEach(b => { b.onclick = () => { PLANWK.showing = b.getAttribute('data-plan-src'); planPaintSheet(); }; });
}
async function planOpenSheet() {
  const me = auth.currentUser && auth.currentUser.uid; if (!me) return;
  const bd = $('plan-backdrop'), f = $('plan-float'); if (!bd || !f) return;
  PLANWK.weekStart = mmMondayOf(todayISO());
  PLANWK.showing = 'own';
  PLANWK.openDay = todayISO();
  bd.style.display = ''; f.style.display = '';
  const body = $('plan-sheet-body');
  if (body) body.innerHTML = `<div class="wempty">${esc(t('access.loading'))}</div>`;
  try { coverSync(); } catch {}
  try {
    const menus = await mmLoadMenus(me);
    NUTRI.myMenus = menus;
    NUTRI.myMenuProposed = menus.filter(x => x.status === 'propuesto' && x.authorRole === 'coach')
      .sort((a, b) => String(b.weekStart || '').localeCompare(String(a.weekStart || '')))[0] || null;
    PLANWK.sc = mmStructureFor(NUTRI.myPlan, (typeof GOALS !== 'undefined' ? GOALS : null), NUTRI.myWishes);
  } catch {}
  planPaintSheet();
}
function planCloseSheet() {
  const bd = $('plan-backdrop'), f = $('plan-float');
  if (bd) bd.style.display = 'none';
  if (f) f.style.display = 'none';
  try { coverSync(); } catch {}
}
/* LA única puerta al editor desde la hoja: la hoja se cierra (y la
   ventana de Comida, si era la superficie de origen) y el editor
   de siempre se abre en la semana que la hoja estaba mostrando. */
function planOpenEditor() {
  PLANWK.editorWeek = PLANWK.weekStart;
  planCloseSheet();
  try { foodCloseAll(); } catch {}
  nutriOpenFloat('menu');
}
/* Las dos puertas a la hoja — la tarjeta de Comida y el botón
   grande del coach — comparten el atributo data-plan-open. */
document.addEventListener('click', e => {
  const b = e.target && e.target.closest ? e.target.closest('[data-plan-open]') : null;
  if (b) planOpenSheet();
});
(function planWireSheet() {
  const c = $('btn-plan-close'); if (c) c.onclick = planCloseSheet;
  const bd = $('plan-backdrop'); if (bd) bd.onclick = planCloseSheet;
  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    const f = $('plan-float');
    if (f && f.style.display !== 'none') planCloseSheet();
  });
})();
/* La tarjeta-puerta de la ventana de Comida: la semana en curso y
   lo planificado para HOY contra su meta, desde los mismos
   documentos; sin menú, el estado honesto y la misma puerta. */
function planCardHTML() {
  const me = auth.currentUser && auth.currentUser.uid;
  const wk = mmMondayOf(todayISO());
  const { own, coachVig } = planResolveMenu(NUTRI.myMenus || [], wk, me);
  const menu = own || coachVig;
  const range = planWeekRange(wk);
  let line, chip = '';
  if (menu) {
    const day = (menu.days || []).find(d => d.date === todayISO()) || null;
    const tot = day ? mmDayTotals(day) : { kcal: 0 };
    const sc = mmStructureFor(NUTRI.myPlan, (typeof GOALS !== 'undefined' ? GOALS : null), NUTRI.myWishes);
    const tgt = (sc.structure && day) ? mmDayTarget(sc.structure, day.dayType) : null;
    const has = !!day && (day.meals || []).some(m => (m.items || []).length);
    line = tgt ? t('planwk.cardLine', { range, kcal: Math.round(tot.kcal), goal: Math.round(tgt.kcal) })
      : t('planwk.cardLineNoGoal', { range, kcal: Math.round(tot.kcal) });
    chip = planBandChip(tot.kcal, tgt ? tgt.kcal : null, has);
  } else {
    line = t('planwk.cardLineEmpty', { range });
  }
  return `<div class="plan-card-in"><div class="plan-card-txt"><b>📅 ${esc(t('planwk.title'))}</b><span>${esc(line)}</span></div>${chip}<button type="button" class="btn-primary plan-card-btn" data-plan-open>${esc(t('planwk.cardBtn'))}</button></div>`;
}
function renderPlanCard() {
  const slot = $('plan-card'); if (!slot) return;
  const me = auth.currentUser && auth.currentUser.uid;
  const show = !!me && ((typeof ROLE !== 'undefined' && ROLE === 'usuario') || NUTRI.myRel || NUTRI.myFollow || NUTRI.myPlan || (typeof IS_OWNER !== 'undefined' && IS_OWNER));
  if (!show) { slot.innerHTML = ''; slot.style.display = 'none'; return; }
  slot.style.display = '';
  slot.innerHTML = planCardHTML();
  /* Refresco en segundo plano: la semana recién construida se ve
     sin reabrir la ventana — la tarjeta se repinta con los menús
     frescos si Comida sigue abierta cuando llegan. */
  mmLoadMenus(me).then(menus => {
    NUTRI.myMenus = menus;
    const ff = $('food-float');
    if (ff && ff.style.display !== 'none' && $('plan-card')) slot.innerHTML = planCardHTML();
  }).catch(() => {});
}

async function mmClientZoneFill() {
  const zones = document.querySelectorAll('[data-mm-zone]');
  for (const z of zones) {
    const sid = z.dataset.mmZone;
    try {
      const menus = await mmLoadMenus(sid);
      const wk = mmMondayOf(todayISO());
      const cur = menus.filter(x => x.weekStart === wk && x.status !== 'archivado')
        .sort((a, b) => (a.status === 'vigente' ? 0 : 1) - (b.status === 'vigente' ? 0 : 1))[0];
      z.innerHTML = cur
        ? `<span class="progress-hint">🍽️ ${esc(t('menu.consoleState', { state: t('menu.status.' + cur.status) }))} · ${esc(cur.authorRole === 'coach' ? t('menu.byCoach') : t('menu.byYou'))}</span>`
        : `<span class="progress-hint">${esc(t('menu.empty'))}</span>`;
    } catch { z.innerHTML = ''; }
  }
}

/* ── AUTH-297: biblioteca de comidas preparadas + «Llenar mi día» ──
   La biblioteca vive en app_settings/prepared_meals (patrón de
   catálogo de la casa: lectura con sesión; escritura solo por la
   vía del propietario/script de carga). Cada comida preparada se
   reconstruyó con ingredientes y gramos concretos y sus totales se
   CALCULARON desde la tabla verificada de la app (FOOD_REF) más los
   ingredientes incorporados con valores USDA FDC bajo la misma
   gobernanza; los números de las recetas de internet NUNCA se
   copiaron: la receta es solo la plantilla (qué lleva y su origen).
   Marcas de cada comida: momentos, objetivos (bajar/mantener/ganar),
   formas derivadas de sus ingredientes (vegetariana, vegana,
   sin gluten por alérgenos, baja en grasa si ≤30 % de sus kcal
   vienen de la grasa — ancla AMDR de grasa 20–35 % de las Guías
   Alimentarias; el punto de corte exacto es decisión de diseño
   declarada) y origen (cocina + tradicional/adaptada). Sin marca de
   texturas blandas en la v1: la investigación no encontró plantillas
   reputadas de dietas de textura modificada. */
let PM_LIB = null;
async function pmLoadLib() {
  if (PM_LIB) return PM_LIB;
  try {
    const s = await getDoc(doc(db, 'app_settings', 'prepared_meals'));
    if (s.exists()) { const d = s.data() || {}; PM_LIB = Array.isArray(d.meals) ? d.meals : []; }
  } catch {}
  return PM_LIB;
}
/* Filtro duro de la biblioteca: el de la casa (mmBlocked: familia en
   los «no quiero», alérgenos por metadatos de la tabla y por nombre,
   texto libre de alergias) MÁS los alérgenos y la familia guardados
   en el propio ingrediente de la biblioteca. Se aplica a la comida
   COMPLETA antes de elegir: un solo ingrediente bloqueado excluye
   la comida entera. */
function pmItemBlocked(item, wishes) {
  if (mmBlocked(item, wishes)) return true;
  if (!wishes) return false;
  const algs = (item && item.allergens) || [];
  for (const a of (wishes.allergies || [])) if (algs.includes(a)) return true;
  if (item && item.family && (wishes.dislikes || []).includes(item.family)) return true;
  return false;
}
function pmMealBlocked(meal, wishes) {
  return ((meal && meal.items) || []).some(it => pmItemBlocked(it, wishes));
}
/* Forma declarada por la persona en su cuestionario: si dejó fuera
   las cuatro familias de carne y pescado, solo entran comidas
   vegetarianas; si además dejó fuera huevos y lácteos, solo
   veganas. Simplificación declarada: se lee SOLO de los «no quiero»
   del cuestionario (no hay campo de forma aparte). */
function pmFormWanted(wishes) {
  const dis = (wishes && wishes.dislikes) || [];
  if (!['pollo', 'carne', 'pescado', 'cerdo'].every(f => dis.includes(f))) return null;
  return (dis.includes('huevos') && dis.includes('lacteos')) ? 'vegana' : 'vegetariana';
}
function pmCandidates(lib, slotName, goal, wishes, formWanted, usedIds) {
  return (lib || []).filter(m =>
    (m.slots || []).includes(slotName) &&
    (!goal || (m.goals || []).includes(goal)) &&
    !(usedIds && usedIds.has(m.id)) &&
    (!formWanted || (m.forms || []).includes(formWanted)) &&
    !pmMealBlocked(m, wishes));
}
function pmScaleItem(base, factor) {
  let g = (Number(base.grams) || 0) * factor;
  g = (Number(base.grams) || 0) <= 10 ? Math.max(1, Math.round(g)) : Math.max(5, Math.round(g / 5) * 5);
  const p = base.per100 || {};
  return {
    name: (typeof LANG !== 'undefined' && LANG === 'en') ? (base.nameEn || base.name) : base.name,
    src: 'meal', refId: base.refId || null, libKey: base.libKey || null, grams: g,
    per100: { kcal: p.kcal, prot: p.prot, carb: p.carb, sugar: p.sugar, fat: p.fat, fiber: p.fiber != null ? p.fiber : null },
    family: base.family || null
  };
}
function pmScaledMeal(meal, target) {
  const baseKcal = (meal.totals && Number(meal.totals.kcal)) || 0;
  let factor = target && target.kcal && baseKcal > 0 ? Number(target.kcal) / baseKcal : 1;
  factor = Math.min(2, Math.max(0.5, factor));
  return (meal.items || []).map(it => pmScaleItem(it, factor));
}
function pmScore(items, target) {
  let kcal = 0, prot = 0, sugar = 0;
  for (const it of items) { const v = mmVals(it); kcal += v.kcal; prot += v.prot; sugar += v.sugar; }
  const dk = target && target.kcal ? Math.abs(kcal - target.kcal) / target.kcal : 0;
  const dp = target && target.prot ? Math.abs(prot - target.prot) / target.prot : 0;
  let score = dk * 2 + dp;
  /* El azúcar es techo también al elegir: pasarse de la parte del
     techo que toca a este momento penaliza la candidatura. */
  if (target && target.azuc > 0 && sugar > target.azuc) score += ((sugar - target.azuc) / target.azuc) * 1.5;
  return score;
}
function pmPickForSlot(lib, slotName, goal, wishes, formWanted, usedIds, target) {
  let best = null;
  for (const m of pmCandidates(lib, slotName, goal, wishes, formWanted, usedIds)) {
    const items = pmScaledMeal(m, target);
    const score = pmScore(items, target);
    if (!best || score < best.score) best = { meal: m, items, score };
  }
  return best;
}
/* Llena UN día del editor: todos sus momentos según la estructura
   de la persona (mmMealTarget/mmDayTarget de AUTH-296: el plan
   aceptado manda; si no, las metas actuales con el motor de la
   Fase 1). Lo generado cae como contenido normal del menú:
   editable, sustituible y con la suma del día viva. Este módulo
   SOLO LEE las metas y la biblioteca; no escribe metas de nadie. */
async function pmFillDay(di) {
  if (!MENU || MENU.readOnly) return;
  const day = MENU.days[di];
  if (!day) return;
  if (day.meals.some(m => (m.items || []).length) && !confirm(t('menu.fillConfirm'))) return;
  toast(t('menu.filling'));
  const lib = await pmLoadLib();
  if (!lib || !lib.length) { toast(t('menu.fillNoLib'), true); return; }
  const wishes = MENU.wishes || null;
  const goal = wishes && wishes.goal ? wishes.goal : null;
  const formWanted = pmFormWanted(wishes);
  const used = new Set();
  const slotMealIds = day.meals.map(() => null);
  const missing = [];
  let filled = 0;
  for (let mi = 0; mi < day.meals.length; mi++) {
    const slot = day.meals[mi];
    const target = MENU.structure ? mmMealTarget(MENU.structure, day.dayType, slot.name) : null;
    const pick = pmPickForSlot(lib, slot.name, goal, wishes, formWanted, used, target);
    if (!pick) { slot.items = []; missing.push(mealName(slot.name)); continue; }
    used.add(pick.meal.id); slotMealIds[mi] = pick.meal.id;
    slot.items = pick.items; filled++;
  }
  /* El azúcar manda como TECHO (criterio OMS de AUTH-296): si el
     día generado se pasa del techo, se intenta cambiar el momento
     más dulce por la alternativa menos dulce que mantenga el día
     dentro de la banda de kcal; si ninguna lo logra, se deja lo
     generado y la suma del día lo muestra, como siempre. */
  const dayTgt = MENU.structure ? mmDayTarget(MENU.structure, day.dayType) : null;
  if (dayTgt && dayTgt.azuc > 0 && filled) {
    const tot = mmDayTotals(day);
    if (tot.sugar > dayTgt.azuc) {
      let si = -1, sv = 0;
      day.meals.forEach((m, i) => { const s = mmMealTotals(m).sugar; if (s > sv) { sv = s; si = i; } });
      if (si >= 0 && slotMealIds[si]) {
        const usedEx = new Set(used); usedEx.delete(slotMealIds[si]);
        const target = mmMealTarget(MENU.structure, day.dayType, day.meals[si].name);
        const alts = pmCandidates(lib, day.meals[si].name, goal, wishes, formWanted, usedEx)
          .map(m => { const items = pmScaledMeal(m, target); return { meal: m, items, sugar: items.reduce((a, it) => a + mmVals(it).sugar, 0) }; })
          .sort((a, b) => a.sugar - b.sugar);
        for (const alt of alts) {
          const oldItems = day.meals[si].items;
          day.meals[si].items = alt.items;
          const tt = mmDayTotals(day);
          const inBand = !dayTgt.kcal || (tt.kcal >= dayTgt.kcal * (1 - MM_TOL) && tt.kcal <= dayTgt.kcal * (1 + MM_TOL));
          if (tt.sugar < tot.sugar && inBand) { used.delete(slotMealIds[si]); used.add(alt.meal.id); slotMealIds[si] = alt.meal.id; break; }
          day.meals[si].items = oldItems;
        }
      }
    }
  }
  mmPaintEditor();
  if (!filled) { toast(t('menu.fillNone'), true); return; }
  toast(t('menu.filled'));
  if (missing.length) setTimeout(() => toast(t('menu.fillPartial', { list: missing.join(', ') }), true), 60);
}

/* Delegación única de clics del paquete (data-mm). */
document.addEventListener('click', async e => {
  const b = e.target && e.target.closest ? e.target.closest('[data-mm]') : null;
  if (!b || b.disabled) return;
  const act = b.dataset.mm;
  if (act === 'open') { nutriOpenFloat('menu'); return; }
  if (act === 'coach-open') { nutriOpenFloat('menucoach', b.dataset.uid); return; }
  if (act === 'coach-back') { nutriOpenFloat('client', b.dataset.uid); return; }
  if (act === 'dec-accept') { await mmDecide(b.dataset.id, 'accept'); return; }
  if (act === 'dec-decline') { await mmDecide(b.dataset.id, 'decline', (($('mm-change-text') || {}).value) || ''); return; }
  if (act === 'dec-change-open') { const p = $('mm-change-panel'); if (p) p.style.display = p.style.display === 'none' ? '' : 'none'; return; }
  if (act === 'dec-chg-reason') {
    if (MENU) MENU.chgReason = b.dataset.r;
    document.querySelectorAll('[data-mm="dec-chg-reason"]').forEach(x => x.classList.toggle('sel', x === b));
    return;
  }
  if (act === 'dec-change-send') { await mmDecide(b.dataset.id, 'change', { reason: (MENU && MENU.chgReason) || 'other', text: (($('mm-change-text') || {}).value) || '' }); return; }
  if (!MENU) return;
  const d = Number(b.dataset.d), m = Number(b.dataset.m), i = Number(b.dataset.i);
  if (act === 'week') {
    MENU.weekStart = planISOAddDays(MENU.weekStart, 7 * Number(b.dataset.dir || 1));
    MENU.copyWeek = planISOAddDays(MENU.weekStart, 7);
    mmLoadWeekIntoEditor(); mmPaintEditor();
  } else if (act === 'dtype') {
    if (MENU.readOnly) return;
    MENU.days[d].dayType = b.dataset.v; mmPaintEditor();
  } else if (act === 'fill-day') {
    await pmFillDay(d);
  } else if (act === 'add-open') {
    MENU.search = { d, m, q: '' }; MENU.swap = null; mmPaintEditor();
  } else if (act === 'search-close') { MENU.search = null; mmPaintEditor(); }
  else if (act === 'pick') {
    const tpl = MENU.cands[Number(b.dataset.idx)];
    if (tpl) { MENU.days[d].meals[m].items.push(mmClone(tpl)); MENU.search = null; mmPaintEditor(); }
  } else if (act === 'swap-open') {
    MENU.swap = { d, m, i }; MENU.swapCands = mmSwapCandidates(MENU.days[d].meals[m].items[i], MENU.wishes); MENU.search = null; mmPaintEditor();
  } else if (act === 'swap-close') { MENU.swap = null; mmPaintEditor(); }
  else if (act === 'swap-pick') {
    const cand = MENU.swapCands[Number(b.dataset.idx)];
    if (cand && MENU.swap) {
      const it = MENU.days[MENU.swap.d].meals[MENU.swap.m].items[MENU.swap.i];
      MENU.days[MENU.swap.d].meals[MENU.swap.m].items[MENU.swap.i] = { ...mmClone(cand), grams: it.grams };
      MENU.swap = null; mmPaintEditor(); toast(t('menu.swapDone'));
    }
  } else if (act === 'item-del') {
    MENU.days[d].meals[m].items.splice(i, 1); mmPaintEditor();
  } else if (act === 'save') { await mmSave(MENU.mode === 'coach' ? 'borrador' : 'vigente'); }
  else if (act === 'save-propose') { await mmSave('propuesto'); }
  else if (act === 'withdraw') {
    if (MENU.menuId) { try { await setDoc(doc(db, 'nutrition_menus', MENU.menuId), { status: 'archivado', updatedAt: serverTimestamp() }, { merge: true }); MENU.menus = await mmLoadMenus(MENU.studentUid); mmLoadWeekIntoEditor(); mmPaintEditor(); toast(t('nutri.saved')); } catch { toast(t('err.createFail'), true); } }
  } else if (act === 'shop') { MENU.view = MENU.view === 'shop' ? 'edit' : 'shop'; mmPaintEditor(); }
  else if (act === 'copy-shift') { MENU.copyWeek = planISOAddDays(MENU.copyWeek, 7 * Number(b.dataset.dir || 1)); mmPaintEditor(); }
  else if (act === 'copy-do') { await mmCopyDo(); }
  else if (act === 'show-coach') { MENU.showing = 'coach'; mmLoadWeekIntoEditor(); mmPaintEditor(); }
  else if (act === 'show-own') { MENU.showing = 'own'; mmLoadWeekIntoEditor(); mmPaintEditor(); }
  else if (act === 'make-mine') {
    MENU.days = mmClone(MENU.days); MENU.menuId = null; MENU.status = null; MENU.authorRole = 'alumno';
    MENU.readOnly = false; MENU.showing = 'own'; mmPaintEditor();
  }
});
document.addEventListener('input', e => {
  const tg = e.target;
  if (!tg || !MENU) return;
  if (tg.matches && tg.matches('[data-mm-grams]')) {
    const d = Number(tg.dataset.d), m = Number(tg.dataset.m), i = Number(tg.dataset.i);
    const it = MENU.days[d] && MENU.days[d].meals[m] && MENU.days[d].meals[m].items[i];
    if (!it) return;
    it.grams = Math.max(0, Number(tg.value) || 0);
    const v = mmVals(it);
    const z = document.getElementById('mm-iv-' + d + '-' + m + '-' + i);
    if (z) z.textContent = `${v.kcal} kcal · ${t('th.protShort')} ${acNum(v.prot)} · ${t('th.carbShort')} ${acNum(v.carb)} · ${t('th.fatShort')} ${acNum(v.fat)}`;
    const mt = document.getElementById('mm-mt-' + d + '-' + m);
    if (mt) { const tot = mmMealTotals(MENU.days[d].meals[m]); const tgt = MENU.structure ? mmMealTarget(MENU.structure, MENU.days[d].dayType, MENU.days[d].meals[m].name) : null; mt.textContent = tot.kcal + ' kcal' + (tgt ? ' / ' + tgt.kcal : ''); }
    mmPaintDayTotals(d);
  } else if (tg.id === 'mm-search-in') {
    if (!MENU.search) return;
    MENU.search.q = tg.value;
    clearTimeout(MENU._mmT);
    MENU._mmT = setTimeout(() => { try { mmPaintSearchResults(); } catch {} }, 220);
  }
});
document.addEventListener('change', e => {
  const tg = e.target;
  if (!tg || !MENU || !(tg.matches && tg.matches('[data-mm-time]'))) return;
  const d = Number(tg.dataset.d), m = Number(tg.dataset.m);
  if (MENU.days[d] && MENU.days[d].meals[m]) MENU.days[d].meals[m].time = tg.value || '';
});
